const STORAGE_KEY = 'vem-comer-settings-v1';

const defaults = {
  sensitivity: 1,
  musicVolume: 0.45,
  sfxVolume: 0.85,
  masterVolume: 0.8,
  quality: 'medium',
  fov: 78,
  shadows: true,
  particles: true,
  vibration: true,
  invertY: false,
  stickScale: 1,
  selectedCharacter: 'iara',
  selectedSkin: 0,
  selectedBanner: 0,
  botDifficulty: 'veteran',
  roundTarget: 4,
};

export class SettingsManager {
  constructor() {
    this.values = { ...defaults };
    this.listeners = new Set();
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (parsed && typeof parsed === 'object') this.values = { ...defaults, ...parsed };
      }
    } catch (error) { /* ignore private-mode errors */ }
  }

  get(key) {
    return this.values[key];
  }

  set(key, value) {
    if (!(key in this.values)) return;
    this.values[key] = value;
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.values)); } catch (error) { /* ignore */ }
    this.listeners.forEach(listener => listener(key, value));
  }

  reset() {
    const keep = {};
    keep.selectedCharacter = this.values.selectedCharacter;
    keep.selectedSkin = this.values.selectedSkin;
    keep.selectedBanner = this.values.selectedBanner;
    this.values = { ...defaults, ...keep };
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.values)); } catch (error) { /* ignore */ }
    this.listeners.forEach(listener => listener('reset', this.values));
  }

  onChange(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
}

export class AudioManager {
  constructor(settings) {
    this.settings = settings;
    this.context = null;
    this.ready = false;
    this.musicNodes = [];
  }

  ensureContext() {
    if (this.ready) return this.context;
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return null;
    this.context = new AudioContextClass();
    this.master = this.context.createGain();
    this.sfxGain = this.context.createGain();
    this.musicGain = this.context.createGain();
    this.sfxGain.connect(this.master);
    this.musicGain.connect(this.master);
    this.master.connect(this.context.destination);
    this.applyVolumes();
    this.ready = true;
    return this.context;
  }

  applyVolumes() {
    if (!this.ready) return;
    this.master.gain.value = this.settings.get('masterVolume');
    this.sfxGain.gain.value = this.settings.get('sfxVolume');
    this.musicGain.gain.value = this.settings.get('musicVolume') * 0.55;
  }

  resume() {
    const context = this.ensureContext();
    if (context && context.state === 'suspended') context.resume();
  }

  playTone({ frequency = 220, duration = 0.18, type = 'sine', gain = 0.2, sweep = null, delay = 0, destination = 'sfx' }) {
    const context = this.ensureContext();
    if (!context) return;
    const start = context.currentTime + delay;
    const osc = context.createOscillator();
    const gainNode = context.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, start);
    if (sweep) {
      if (Array.isArray(sweep)) osc.frequency.exponentialRampToValueAtTime(Math.max(10, sweep[1]), start + duration);
      else osc.frequency.exponentialRampToValueAtTime(Math.max(10, sweep), start + duration);
    }
    gainNode.gain.setValueAtTime(0.0001, start);
    gainNode.gain.exponentialRampToValueAtTime(Math.max(0.001, gain), start + Math.min(duration * 0.2, 0.03));
    gainNode.gain.exponentialRampToValueAtTime(0.0001, start + duration);
    osc.connect(gainNode).connect(destination === 'music' ? this.musicGain : this.sfxGain);
    osc.start(start);
    osc.stop(start + duration + 0.02);
  }

  playNoise({ duration = 0.16, gain = 0.18, filter = 600, sweep = null, delay = 0 }) {
    const context = this.ensureContext();
    if (!context) return;
    const sampleCount = Math.floor(context.sampleRate * duration);
    const buffer = context.createBuffer(1, sampleCount, context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < sampleCount; i += 1) data[i] = (Math.random() * 2 - 1) * (1 - i / sampleCount);
    const source = context.createBufferSource();
    source.buffer = buffer;
    const filterNode = context.createBiquadFilter();
    filterNode.type = 'lowpass';
    filterNode.frequency.setValueAtTime(filter, context.currentTime + delay);
    if (sweep) filterNode.frequency.exponentialRampToValueAtTime(Math.max(50, sweep), context.currentTime + delay + duration);
    const gainNode = context.createGain();
    gainNode.gain.setValueAtTime(gain, context.currentTime + delay);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, context.currentTime + delay + duration);
    source.connect(filterNode).connect(gainNode).connect(this.sfxGain);
    source.start(context.currentTime + delay);
  }

  ui(kind = 'click') {
    this.resume();
    if (kind === 'click') this.playTone({ frequency: 720, duration: 0.06, type: 'triangle', gain: 0.05 });
    if (kind === 'confirm') {
      this.playTone({ frequency: 540, duration: 0.08, type: 'triangle', gain: 0.07 });
      this.playTone({ frequency: 780, duration: 0.1, type: 'triangle', gain: 0.06, delay: 0.07 });
    }
    if (kind === 'back') this.playTone({ frequency: 430, duration: 0.09, type: 'triangle', gain: 0.05 });
    if (kind === 'error') this.playTone({ frequency: 220, duration: 0.14, type: 'sawtooth', gain: 0.07, sweep: 90 });
    if (kind === 'deploy') this.playTone({ frequency: 300, duration: 0.32, type: 'sawtooth', gain: 0.09, sweep: [300, 90] });
  }

  shot(kind = 'rifle', distance = 0) {
    const falloff = Math.max(0.28, 1 - distance / 70);
    if (kind === 'pistol') {
      this.playNoise({ duration: 0.08, gain: 0.15 * falloff, filter: 1900, sweep: 500 });
      this.playTone({ frequency: 230, duration: 0.05, type: 'square', gain: 0.05 * falloff, sweep: 110 });
    } else if (kind === 'smg') {
      this.playNoise({ duration: 0.06, gain: 0.11 * falloff, filter: 2400, sweep: 700 });
      this.playTone({ frequency: 190, duration: 0.04, type: 'square', gain: 0.045 * falloff, sweep: 90 });
    } else if (kind === 'shotgun') {
      this.playNoise({ duration: 0.18, gain: 0.24 * falloff, filter: 1200, sweep: 260 });
      this.playTone({ frequency: 130, duration: 0.14, type: 'sawtooth', gain: 0.08 * falloff, sweep: 55 });
    } else if (kind === 'sniper') {
      this.playNoise({ duration: 0.2, gain: 0.25 * falloff, filter: 1600, sweep: 320 });
      this.playTone({ frequency: 175, duration: 0.18, type: 'sawtooth', gain: 0.1 * falloff, sweep: 55 });
    } else {
      this.playNoise({ duration: 0.09, gain: 0.16 * falloff, filter: 2200, sweep: 520 });
      this.playTone({ frequency: 215, duration: 0.06, type: 'square', gain: 0.06 * falloff, sweep: 85 });
    }
  }

  impact() {
    this.playNoise({ duration: 0.05, gain: 0.07, filter: 900 });
  }

  hit() {
    this.playTone({ frequency: 900, duration: 0.045, type: 'square', gain: 0.08, sweep: 500 });
  }

  kill() {
    this.playTone({ frequency: 640, duration: 0.08, type: 'triangle', gain: 0.08 });
    this.playTone({ frequency: 940, duration: 0.1, type: 'triangle', gain: 0.07, delay: 0.07 });
  }

  reload() {
    this.playTone({ frequency: 420, duration: 0.07, type: 'square', gain: 0.06 });
    this.playTone({ frequency: 300, duration: 0.08, type: 'square', gain: 0.05, delay: 0.16 });
    this.playTone({ frequency: 620, duration: 0.07, type: 'square', gain: 0.07, delay: 0.35 });
  }

  jump() {
    this.playTone({ frequency: 300, duration: 0.1, type: 'sine', gain: 0.045, sweep: 520 });
  }

  footstep(distance = 0) {
    const gain = Math.max(0.02, 0.07 - distance / 400);
    this.playNoise({ duration: 0.06, gain, filter: 420, sweep: 190 });
  }

  ability(kind = 'normal') {
    if (kind === 'special') {
      this.playTone({ frequency: 320, duration: 0.3, type: 'sawtooth', gain: 0.12, sweep: [320, 110] });
      this.playNoise({ duration: 0.25, gain: 0.11, filter: 1500, sweep: 320 });
    } else {
      this.playTone({ frequency: 480, duration: 0.13, type: 'triangle', gain: 0.09, sweep: [480, 190] });
      this.playNoise({ duration: 0.12, gain: 0.06, filter: 1000 });
    }
  }

  bombBeep(rate = 1) {
    this.playTone({ frequency: 900, duration: 0.06, type: 'square', gain: 0.09 });
    if (rate > 1.4) this.playTone({ frequency: 1150, duration: 0.05, type: 'square', gain: 0.07, delay: 0.08 });
  }

  plant() {
    this.playTone({ frequency: 420, duration: 0.12, type: 'triangle', gain: 0.08 });
    this.playTone({ frequency: 660, duration: 0.16, type: 'triangle', gain: 0.07, delay: 0.1 });
  }

  defuse() {
    this.playTone({ frequency: 560, duration: 0.16, type: 'triangle', gain: 0.08 });
    this.playTone({ frequency: 760, duration: 0.22, type: 'triangle', gain: 0.07, delay: 0.12 });
  }

  explosion() {
    this.playNoise({ duration: 0.55, gain: 0.4, filter: 1600, sweep: 70 });
    this.playTone({ frequency: 80, duration: 0.65, type: 'sawtooth', gain: 0.16, sweep: 30 });
    this.playNoise({ duration: 0.8, gain: 0.2, filter: 500, sweep: 60, delay: 0.07 });
  }

  roundStart() {
    this.playTone({ frequency: 420, duration: 0.15, type: 'triangle', gain: 0.1 });
    this.playTone({ frequency: 640, duration: 0.2, type: 'triangle', gain: 0.09, delay: 0.16 });
  }

  victory() {
    const notes = [520, 660, 790, 1050];
    notes.forEach((frequency, index) => this.playTone({ frequency, duration: 0.3, type: 'triangle', gain: 0.12, delay: index * 0.13 }));
  }

  defeat() {
    const notes = [380, 300, 230, 170];
    notes.forEach((frequency, index) => this.playTone({ frequency, duration: 0.36, type: 'sawtooth', gain: 0.1, delay: index * 0.15 }));
  }

  ambience() {
    if (!this.ready) return;
    this.playTone({ frequency: 58, duration: 2.5, type: 'sine', gain: 0.05, destination: 'music' });
    this.playTone({ frequency: 87, duration: 2.8, type: 'sine', gain: 0.03, destination: 'music', delay: 0.4 });
  }
}

export class TeamManager {
  constructor() {
    this.reset();
  }

  reset() {
    this.attackers = [];
    this.defenders = [];
    this.attackersScore = 0;
    this.defendersScore = 0;
    this.roundAttackersWins = 0;
  }

  register(entity, team) {
    if (team === 'attackers') this.attackers.push(entity);
    else this.defenders.push(entity);
  }

  unregister(entity) {
    this.attackers = this.attackers.filter(e => e !== entity);
    this.defenders = this.defenders.filter(e => e !== entity);
  }

  clear() {
    this.attackers = [];
    this.defenders = [];
  }

  alive(team) {
    return this.get(team).filter(entity => entity.isAlive && entity.isAlive()).length;
  }

  get(team) {
    return team === 'attackers' ? this.attackers : this.defenders;
  }

  opponent(team) {
    return team === 'attackers' ? 'defenders' : 'attackers';
  }

  player(team) {
    return this.get(team).find(entity => entity.isPlayer);
  }

  playersAliveCount() {
    return {
      attackers: this.alive('attackers'),
      defenders: this.alive('defenders'),
    };
  }

  addScore(team, amount = 1) {
    if (team === 'attackers') this.attackersScore += amount;
    else this.defendersScore += amount;
  }

  resetRoundState() {
    [...this.attackers, ...this.defenders].forEach(entity => {
      if (entity.resetRound) entity.resetRound();
    });
  }

  resetMatch() {
    this.attackersScore = 0;
    this.defendersScore = 0;
  }
}

import * as THREE from 'three';

const lowSegments = { capsule: 5, sphere: 8, cylinder: 8 };

function mat(color, opts = {}) {
  return new THREE.MeshLambertMaterial({
    color: new THREE.Color(color),
    emissive: new THREE.Color(opts.emissive || '#000000'),
    emissiveIntensity: opts.emissiveIntensity || 0,
    transparent: !!opts.transparent,
    opacity: opts.opacity ?? 1,
  });
}

function capsule(radius, length, color, opts = {}) {
  const mesh = new THREE.Mesh(new THREE.CapsuleGeometry(radius, length, lowSegments.capsule, lowSegments.sphere), mat(color, opts));
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function sphere(radius, color, opts = {}) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, lowSegments.sphere, lowSegments.sphere / 2), mat(color, opts));
  mesh.castShadow = true;
  return mesh;
}

function box(w, h, d, color, opts = {}) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color, opts));
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function cyl(rt, rb, h, color, opts = {}) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, lowSegments.cylinder), mat(color, opts));
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

function plane(w, h, color, opts = {}) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), mat(color, opts));
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

export class CharacterMesh {
  constructor(character, skinIndex = 0) {
    this.character = character;
    this.skinIndex = skinIndex % character.skins.length;
    this.colors = character.skins[this.skinIndex].colors;
    this.group = new THREE.Group();
    this.group.name = `character-${character.id}`;
    this.group.userData.isCharacter = true;
    this.group.userData.characterId = character.id;
    this.buildBody();
    this.buildGear();
    this.buildHair();
    this.buildFace();
    this.buildWeaponProp();
    this.parts = this.group.userData.parts;
    this.action = { type: 'idle', time: 0 };
    this.gait = 0;
    this.lastFootstep = 0;
  }

  buildBody() {
    const skin = this.colors.skin;
    const cloth = this.colors.cloth;
    const root = new THREE.Group();
    root.position.y = 0;
    this.bodyRoot = root;
    this.group.add(root);

    // Lower body / hips.
    const hips = capsule(0.245, 0.18, skin);
    hips.position.y = 0.82;
    hips.scale.set(1.02, 1, 1);
    root.add(hips);

    // Trousers with modest tactical fit.
    const trousers = capsule(0.235, 0.2, cloth);
    trousers.position.y = 0.84;
    trousers.scale.set(1.08, 0.92, 1);
    root.add(trousers);

    // Torso and chest silhouette; tactical top covers shoulders and chest.
    const torso = capsule(0.28, 0.38, cloth);
    torso.position.y = 1.2;
    torso.scale.set(1.05, 1.02, 0.92);
    root.add(torso);

    const upperTorso = capsule(0.255, 0.32, cloth);
    upperTorso.position.y = 1.42;
    upperTorso.scale.set(1.03, 1, 0.94);
    root.add(upperTorso);

    const chestPlate = box(0.46, 0.34, 0.2, this.colors.gear);
    chestPlate.position.set(0, 1.35, 0.025);
    root.add(chestPlate);

    const collar = box(0.42, 0.09, 0.16, this.colors.accent, { emissive: this.colors.accent, emissiveIntensity: 0.18 });
    collar.position.set(0, 1.54, 0.02);
    root.add(collar);

    const neck = cyl(0.075, 0.075, 0.1, skin);
    neck.position.y = 1.58;
    root.add(neck);

    const head = sphere(0.155, skin);
    head.position.y = 1.74;
    root.add(head);

    const shoulders = new THREE.Group();
    [-0.25, 0.25].forEach(x => {
      const shoulder = sphere(0.08, cloth);
      shoulder.position.set(x, 1.5, 0);
      shoulders.add(shoulder);
    });
    root.add(shoulders);

    // Arms.
    this.leftArm = new THREE.Group();
    this.rightArm = new THREE.Group();
    root.add(this.leftArm, this.rightArm);
    [this.leftArm, this.rightArm].forEach((arm, index) => {
      const upper = capsule(0.06, 0.16, cloth);
      upper.position.y = -0.16;
      const lower = capsule(0.055, 0.16, index === 0 ? cloth : this.colors.gear);
      lower.position.y = -0.4;
      const glove = sphere(0.065, this.colors.gear);
      glove.position.y = -0.58;
      arm.add(upper, lower, glove);
      arm.position.set(index === 0 ? -0.25 : 0.25, 1.48, 0);
      arm.rotation.z = index === 0 ? 0.25 : -0.25;
    });

    // Legs.
    this.leftLeg = new THREE.Group();
    this.rightLeg = new THREE.Group();
    root.add(this.leftLeg, this.rightLeg);
    [this.leftLeg, this.rightLeg].forEach((leg, index) => {
      const thigh = capsule(0.08, 0.2, index === 0 ? cloth : cloth);
      thigh.position.y = -0.22;
      const shin = capsule(0.07, 0.18, this.colors.gear);
      shin.position.y = -0.55;
      const boot = box(0.1, 0.07, 0.19, '#25282d');
      boot.position.set(0, -0.72, 0.03);
      leg.add(thigh, shin, boot);
      leg.position.set(index === 0 ? -0.115 : 0.115, 0.8, 0);
    });

    root.userData.parts = {
      torso,
      upperTorso,
      head,
      chestPlate,
      collar,
      leftArm: this.leftArm,
      rightArm: this.rightArm,
      leftLeg: this.leftLeg,
      rightLeg: this.rightLeg,
      shoulders,
    };
  }

  buildGear() {
    const accent = this.colors.accent;
    const gear = this.colors.gear;
    const root = this.bodyRoot;

    const belt = box(0.44, 0.07, 0.18, gear);
    belt.position.y = 0.95;
    root.add(belt);

    const pouch = box(0.12, 0.09, 0.05, accent, { emissive: accent, emissiveIntensity: 0.2 });
    pouch.position.set(0.14, 0.95, 0.09);
    root.add(pouch);

    const vestBack = box(0.36, 0.28, 0.08, gear);
    vestBack.position.set(0, 1.33, -0.1);
    root.add(vestBack);

    const reactor = cyl(0.05, 0.05, 0.08, accent, { emissive: accent, emissiveIntensity: 0.3 });
    reactor.position.set(0, 1.23, -0.13);
    root.add(reactor);

    // Role-specific head gear.
    const role = this.character.role;
    if (role === 'defense' || role === 'assault') {
      const helmet = sphere(0.16, gear);
      helmet.position.set(0, 1.79, -0.015);
      helmet.scale.set(1.05, 0.88, 1.05);
      root.add(helmet);
      const visor = box(0.18, 0.045, 0.06, accent, { emissive: accent, emissiveIntensity: 0.42 });
      visor.position.set(0, 1.76, 0.13);
      root.add(visor);
    } else if (role === 'recon') {
      const goggles = box(0.23, 0.07, 0.06, '#20242a');
      goggles.position.set(0, 1.75, 0.12);
      root.add(goggles);
      const lens = box(0.06, 0.035, 0.01, accent, { emissive: accent, emissiveIntensity: 0.45 });
      lens.position.set(0.05, 1.75, 0.155);
      root.add(lens);
      const headset = torusMesh(0.14, 0.018, gear);
      headset.rotation.x = Math.PI / 2;
      headset.position.y = 1.74;
      root.add(headset);
    } else if (role === 'support') {
      const headband = box(0.26, 0.05, 0.07, gear);
      headband.position.y = 1.82;
      root.add(headband);
      const medicCross = box(0.035, 0.015, 0.02, accent, { emissive: accent, emissiveIntensity: 0.4 });
      medicCross.position.set(0, 1.38, 0.14);
      root.add(medicCross);
    } else {
      const band = box(0.23, 0.04, 0.07, gear);
      band.position.y = 1.81;
      root.add(band);
      const unit = cyl(0.025, 0.025, 0.09, accent, { emissive: accent, emissiveIntensity: 0.35 });
      unit.position.set(0.1, 1.28, -0.12);
      root.add(unit);
    }

    // Boots and knee protectors.
    [this.leftLeg, this.rightLeg].forEach(leg => {
      const knee = box(0.13, 0.11, 0.11, gear);
      knee.position.set(0, -0.34, 0.02);
      leg.add(knee);
    });

    function torusMesh(radius, tube, color) {
      const geometry = new THREE.TorusGeometry(radius, tube, lowSegments.capsule, lowSegments.sphere);
      const mesh = new THREE.Mesh(geometry, mat(color));
      mesh.castShadow = true;
      return mesh;
    }
  }

  buildHair() {
    const hairColor = this.colors.hair;
    const root = this.bodyRoot;
    const hair = new THREE.Group();
    const role = this.character.role;
    if (role === 'assault' || role === 'recon') {
      const ponytail = capsule(0.05, 0.18, hairColor);
      ponytail.position.set(0, 1.66, -0.14);
      ponytail.rotation.x = -0.35;
      hair.add(ponytail);
      const top = sphere(0.135, hairColor);
      top.position.set(0, 1.82, -0.03);
      top.scale.set(1.08, 0.72, 1.02);
      hair.add(top);
    } else if (role === 'support') {
      const bun = sphere(0.09, hairColor);
      bun.position.set(0, 1.77, -0.11);
      hair.add(bun);
      const cap = sphere(0.13, hairColor);
      cap.position.set(0, 1.83, -0.02);
      cap.scale.set(1.05, 0.58, 1.0);
      hair.add(cap);
    } else if (role === 'defense') {
      const braids = [];
      for (let i = 0; i < 4; i += 1) {
        const braid = capsule(0.025, 0.16, hairColor);
        braid.position.set((i - 1.5) * 0.055, 1.68, -0.14);
        braid.rotation.x = -0.18;
        braids.push(braid);
      }
      hair.add(...braids);
    } else {
      const longHair = capsule(0.07, 0.28, hairColor);
      longHair.position.set(0, 1.62, -0.13);
      hair.add(longHair);
    }
    root.add(hair);
    root.userData.parts.hair = hair;
  }

  buildFace() {
    const root = this.bodyRoot;
    const eyes = new THREE.Group();
    [-0.06, 0.06].forEach(x => {
      const eye = sphere(0.021, '#121620');
      eye.position.set(x, 1.75, 0.14);
      eye.scale.set(1, 0.8, 0.5);
      eyes.add(eye);
    });
    const visor = box(0.09, 0.012, 0.008, this.colors.accent, { emissive: this.colors.accent, emissiveIntensity: 0.3 });
    visor.position.set(0, 1.79, 0.145);
    root.add(eyes, visor);
  }

  buildWeaponProp() {
    const prop = new THREE.Group();
    const color = '#2a2f36';
    const accent = this.colors.accent;
    const barrel = cyl(0.02, 0.02, 0.36, color);
    barrel.rotation.z = Math.PI / 2;
    barrel.position.x = 0.18;
    prop.add(barrel);
    const body = box(0.18, 0.06, 0.05, color);
    body.position.x = 0.04;
    prop.add(body);
    const handle = box(0.05, 0.09, 0.04, color);
    handle.position.set(-0.03, -0.05, 0);
    prop.add(handle);
    const glow = box(0.02, 0.02, 0.02, accent, { emissive: accent, emissiveIntensity: 0.5 });
    glow.position.set(0.13, 0.03, 0);
    prop.add(glow);
    prop.position.set(0.19, 1.4, 0.12);
    prop.rotation.set(0, -0.15, 0);
    this.bodyRoot.add(prop);
    this.weaponProp = prop;
    rootProp(this.bodyRoot).userData.parts.weaponProp = prop;
  }

  setSkin(index) {
    this.skinIndex = index % this.character.skins.length;
    // Simple visual re-accent: could be expanded later to full material swap.
    this.bodyRoot.userData.parts.collar.material.color.set(this.colors.accent);
  }

  setAction(type, time = 0) {
    this.action.type = type;
    this.action.time = time;
  }

  animate(dt, speed = 0, grounded = true, alive = true) {
    if (!this.bodyRoot) return;
    this.gait += dt * (speed * 2.2 + 0.4);
    const p = this.bodyRoot.userData.parts;
    const time = this.action.time;
    this.action.time += dt;
    if (!alive) {
      this.bodyRoot.rotation.x = THREE.MathUtils.lerp(this.bodyRoot.rotation.x, 1.4, Math.min(1, dt * 4));
      this.bodyRoot.position.y = THREE.MathUtils.lerp(this.bodyRoot.position.y, -0.18, Math.min(1, dt * 4));
      p.leftArm.rotation.z = THREE.MathUtils.lerp(p.leftArm.rotation.z, 1.3, dt * 5);
      p.rightArm.rotation.z = THREE.MathUtils.lerp(p.rightArm.rotation.z, -1.3, dt * 5);
      return;
    }
    this.bodyRoot.rotation.x = THREE.MathUtils.lerp(this.bodyRoot.rotation.x, 0, dt * 6);
    this.bodyRoot.position.y = THREE.MathUtils.lerp(this.bodyRoot.position.y, 0, dt * 6);
    const walk = THREE.MathUtils.clamp(speed / 7.5, 0, 1);
    const swing = Math.sin(this.gait * 2.6) * 0.42 * walk;
    const lift = Math.sin(this.gait * 5.2) * 0.04 * walk;
    this.bodyRoot.position.y += lift;
    p.leftLeg.rotation.x = swing;
    p.rightLeg.rotation.x = -swing;
    p.leftArm.rotation.x = -swing * 0.5;
    p.rightArm.rotation.x = swing * 0.45;
    if (!grounded) {
      p.leftLeg.rotation.x = -0.25;
      p.rightLeg.rotation.x = 0.28;
      p.leftArm.rotation.x = -0.35;
      p.rightArm.rotation.x = -0.3;
    }
    if (this.action.type === 'shoot' && this.action.time < 0.16) {
      const progress = this.action.time / 0.16;
      p.rightArm.rotation.x = -0.35 + progress * 0.16;
      p.rightArm.rotation.z = -0.25 + progress * 0.12;
      this.weaponProp.position.z = 0.12 + progress * 0.012;
    } else {
      this.weaponProp.position.z = THREE.MathUtils.lerp(this.weaponProp.position.z, 0.12, dt * 5);
    }
    if (this.action.type === 'reload' && this.action.time < 1.6) {
      p.leftArm.rotation.x = -0.6;
      p.rightArm.rotation.x = -0.55;
      this.weaponProp.rotation.z = Math.sin(this.action.time * 4) * 0.14;
    } else {
      this.weaponProp.rotation.z = THREE.MathUtils.lerp(this.weaponProp.rotation.z, 0, dt * 5);
    }
    if (this.action.type === 'ability' && this.action.time < 0.55) {
      const wave = Math.sin(this.action.time * 14) * 0.22;
      this.bodyRoot.rotation.y = wave;
      p.leftArm.rotation.z = 0.25 + Math.abs(wave) * 0.6;
      p.rightArm.rotation.z = -0.25 - Math.abs(wave) * 0.6;
    } else {
      this.bodyRoot.rotation.y = THREE.MathUtils.lerp(this.bodyRoot.rotation.y, 0, dt * 5);
    }
    if (this.action.type === 'plantBomb' && this.action.time < 1.1) {
      p.rightArm.rotation.x = -0.7;
      p.leftArm.rotation.x = -0.55;
      this.bodyRoot.position.y = -0.05;
    }
    if (this.action.type === 'defuseBomb' && this.action.time < 1.1) {
      p.rightArm.rotation.x = -0.62;
      p.leftArm.rotation.x = -0.5;
      this.bodyRoot.position.y = -0.08;
    }
  }
}

function rootProp(object) {
  let current = object;
  while (current && !current.userData.isCharacter) current = current.parent;
  return current || object;
}

export function createCharacterMesh(character, skinIndex = 0) {
  return new CharacterMesh(character, skinIndex);
}

import * as THREE from 'three';

export class MapBuilder {
  constructor(scene, quality = 'medium') {
    this.scene = scene;
    this.quality = quality;
    this.colliders = [];
    this.meshes = [];
    this.siteZones = [
      { id: 'A', center: new THREE.Vector2(-18, 0), radius: 6 },
      { id: 'B', center: new THREE.Vector2(18, 0), radius: 6 },
    ];
    this.spawnPoints = {
      attackers: [
        new THREE.Vector3(-10, 0, 18),
        new THREE.Vector3(-5, 0, 18.5),
        new THREE.Vector3(0, 0, 18),
        new THREE.Vector3(5, 0, 18.5),
        new THREE.Vector3(10, 0, 18),
      ],
      defenders: [
        new THREE.Vector3(-10, 0, -18),
        new THREE.Vector3(-5, 0, -18.5),
        new THREE.Vector3(0, 0, -18),
        new THREE.Vector3(5, 0, -18.5),
        new THREE.Vector3(10, 0, -18),
      ],
    };
    this.patrolPoints = {
      defenders: [
        new THREE.Vector3(-18, 0, -2),
        new THREE.Vector3(-13, 0, 4),
        new THREE.Vector3(0, 0, -3),
        new THREE.Vector3(13, 0, 4),
        new THREE.Vector3(18, 0, -2),
        new THREE.Vector3(-4, 0, -8),
        new THREE.Vector3(4, 0, -8),
      ],
      attackers: [
        new THREE.Vector3(-18, 0, 2),
        new THREE.Vector3(0, 0, 4),
        new THREE.Vector3(18, 0, 2),
        new THREE.Vector3(-12, 0, 9),
        new THREE.Vector3(12, 0, 9),
      ],
    };
    this.effects = [];
    this.group = new THREE.Group();
    scene.add(this.group);
    this.build();
    this.buildGrid();
  }

  build() {
    this.createGround();
    this.createPerimeter();
    this.createArchitecture();
    this.createSites();
    this.createLights();
    this.createProps();
  }

  createGround() {
    const geometry = new THREE.PlaneGeometry(70, 44);
    const material = new THREE.MeshLambertMaterial({ color: 0x12181f });
    const ground = new THREE.Mesh(geometry, material);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    ground.userData.blockBullet = true;
    this.group.add(ground);
    this.meshes.push(ground);

    const gridHelper = new THREE.GridHelper(70, 70, 0x2a3442, 0x1c232c);
    gridHelper.position.y = 0.02;
    gridHelper.material.opacity = 0.18;
    gridHelper.material.transparent = true;
    this.group.add(gridHelper);

    const accentFloor = new THREE.Mesh(
      new THREE.PlaneGeometry(70, 44),
      new THREE.MeshBasicMaterial({ color: 0x0a0d13, transparent: true, opacity: 0.28 }),
    );
    accentFloor.rotation.x = -Math.PI / 2;
    accentFloor.position.y = 0.01;
    this.group.add(accentFloor);
  }

  createPerimeter() {
    const wallMat = new THREE.MeshLambertMaterial({ color: 0x2c333c });
    const dims = [
      { x: 0, z: 22, width: 70, depth: 1, height: 5 },
      { x: 0, z: -22, width: 70, depth: 1, height: 5 },
      { x: 35, z: 0, width: 1, depth: 45, height: 5 },
      { x: -35, z: 0, width: 1, depth: 45, height: 5 },
    ];
    dims.forEach(dim => this.addBox(dim, wallMat));
  }

  createArchitecture() {
    const concrete = new THREE.MeshLambertMaterial({ color: 0x3a4350 });
    const darkMetal = new THREE.MeshLambertMaterial({ color: 0x232a33 });
    const accent = new THREE.MeshLambertMaterial({ color: 0x14202b, emissive: 0x1c3646, emissiveIntensity: 0.35 });

    const structures = [
      { x: -10, z: -11, width: 14, depth: 2.2, height: 4, material: concrete },
      { x: 10, z: 11, width: 14, depth: 2.2, height: 4, material: concrete },
      { x: -10, z: 11, width: 8, depth: 2.2, height: 4, material: concrete },
      { x: 10, z: -11, width: 8, depth: 2.2, height: 4, material: concrete },
      { x: 0, z: 0, width: 2.4, depth: 16, height: 5, material: darkMetal },
      { x: -18, z: 7, width: 8, depth: 1.6, height: 3.2, material: concrete },
      { x: 18, z: -7, width: 8, depth: 1.6, height: 3.2, material: concrete },
      { x: -20, z: -10, width: 2, depth: 12, height: 3.6, material: concrete },
      { x: 20, z: 10, width: 2, depth: 12, height: 3.6, material: concrete },
      { x: -4, z: 4, width: 3.4, depth: 3.4, height: 2.2, material: darkMetal },
      { x: 4, z: -4, width: 3.4, depth: 3.4, height: 2.2, material: darkMetal },
      { x: -13, z: 2, width: 4, depth: 3, height: 2.4, material: accent },
      { x: 13, z: -2, width: 4, depth: 3, height: 2.4, material: accent },
      { x: -28, z: -14, width: 7, depth: 5, height: 2.6, material: concrete },
      { x: 28, z: 14, width: 7, depth: 5, height: 2.6, material: concrete },
    ];
    structures.forEach(struct => this.addBox(struct, struct.material || concrete));

    // Strategic pillars.
    [[-25, 0], [25, 0], [-12, -18], [12, 18]].forEach(([x, z]) => {
      this.addBox({ x, z, width: 1.5, depth: 1.5, height: 4.5 }, darkMetal);
    });
  }

  createSites() {
    this.siteZones.forEach(site => {
      const color = site.id === 'A' ? 0xff5b2e : 0x42d9ee;
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(site.radius - 0.55, site.radius, 32),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.42, side: THREE.DoubleSide }),
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.set(site.center.x, 0.05, site.center.y);
      this.group.add(ring);
      const inner = new THREE.Mesh(
        new THREE.CircleGeometry(site.radius - 1.1, 32),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.07, side: THREE.DoubleSide }),
      );
      inner.rotation.x = -Math.PI / 2;
      inner.position.set(site.center.x, 0.035, site.center.y);
      this.group.add(inner);
      const label = new THREE.Sprite(new THREE.SpriteMaterial({
        map: makeSiteLabel(site.id, site.id === 'A' ? '#ff5b2e' : '#42d9ee'),
        transparent: true,
        opacity: 0.9,
      }));
      label.position.set(site.center.x, 3.4, site.center.y);
      label.scale.set(3.2, 1.6, 1);
      this.group.add(label);
      const light = new THREE.PointLight(color, 0.65, 18, 2);
      light.position.set(site.center.x, 3.2, site.center.y);
      this.group.add(light);
    });
  }

  createLights() {
    const ambient = new THREE.AmbientLight(0x77808c, this.quality === 'low' ? 0.65 : 0.45);
    this.group.add(ambient);
    const hemisphere = new THREE.HemisphereLight(0x5d6a7a, 0x11151b, 0.5);
    this.group.add(hemisphere);
    const directional = new THREE.DirectionalLight(0xffe8d2, this.quality === 'low' ? 0.45 : 0.75);
    directional.position.set(18, 28, -14);
    if (this.quality === 'low') directional.castShadow = false;
    else {
      directional.castShadow = true;
      directional.shadow.mapSize.set(this.quality === 'high' ? 2048 : 1024, this.quality === 'high' ? 2048 : 1024);
      directional.shadow.camera.near = 1;
      directional.shadow.camera.far = 90;
      directional.shadow.camera.left = -48;
      directional.shadow.camera.right = 48;
      directional.shadow.camera.top = 40;
      directional.shadow.camera.bottom = -40;
      directional.shadow.bias = -0.0006;
    }
    this.group.add(directional);
    this.directional = directional;

    const warmLight = new THREE.PointLight(0xff6f47, 0.55, 26, 2);
    warmLight.position.set(-14, 4, 10);
    this.group.add(warmLight);
    const coolLight = new THREE.PointLight(0x3fe6f0, 0.5, 26, 2);
    coolLight.position.set(14, 4, -10);
    this.group.add(coolLight);
  }

  createProps() {
    const palette = [0x353f4a, 0x2b323b, 0x404a55, 0x1f272f];
    const props = [
      { x: -23, z: 5, w: 1.5, d: 1.5, h: 1.5 },
      { x: -17, z: -4, w: 1.5, d: 1.5, h: 1.2 },
      { x: -8, z: 7, w: 1.3, d: 1.3, h: 1.3 },
      { x: -2, z: -7, w: 1.5, d: 1.5, h: 1.4 },
      { x: 3, z: 7, w: 1.5, d: 1.5, h: 1.3 },
      { x: 9, z: -7, w: 1.5, d: 1.5, h: 1.5 },
      { x: 17, z: 4, w: 1.5, d: 1.5, h: 1.2 },
      { x: 23, z: -5, w: 1.5, d: 1.5, h: 1.5 },
      { x: -27, z: -6, w: 2, d: 2, h: 2.2 },
      { x: 27, z: 6, w: 2, d: 2, h: 2.2 },
      { x: -6, z: -17, w: 3.5, d: 2, h: 2.5 },
      { x: 6, z: 17, w: 3.5, d: 2, h: 2.5 },
    ];
    props.forEach((prop, index) => {
      const material = new THREE.MeshLambertMaterial({ color: palette[index % palette.length] });
      this.addBox({ x: prop.x, z: prop.z, width: prop.w, depth: prop.d, height: prop.h }, material);
    });

    const barrelGeometry = new THREE.CylinderGeometry(0.45, 0.45, 1.1, 10);
    const barrelPositions = [
      [-15, 0.55, 3], [15, 0.55, -3], [-26, 0.55, 2], [26, 0.55, -2], [-11, 0.55, -15], [11, 0.55, 15],
    ];
    const barrelMat = new THREE.MeshLambertMaterial({ color: 0x404b58 });
    const barrelAccent = new THREE.MeshLambertMaterial({ color: 0x1b2a36, emissive: 0x213a4a, emissiveIntensity: 0.35 });
    barrelPositions.forEach((pos, i) => {
      const barrel = new THREE.Mesh(barrelGeometry, i % 2 ? barrelAccent : barrelMat);
      barrel.position.set(pos[0], pos[1], pos[2]);
      barrel.castShadow = true;
      barrel.receiveShadow = true;
      this.group.add(barrel);
      this.meshes.push(barrel);
      this.colliders.push(makeCollider(pos[0], pos[2], 0.95, 0.95, 1.1));
    });

    // Tactical signage.
    const signs = [
      { text: 'SITE A', color: '#ff5b2e', pos: [-18, 2.8, 0] },
      { text: 'SITE B', color: '#42d9ee', pos: [18, 2.8, 0] },
      { text: 'VC', color: '#f4f0e8', pos: [0, 2.6, 18.6] },
    ];
    signs.forEach(sign => {
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: makeTextTexture(sign.text, sign.color), transparent: true }));
      sprite.position.set(sign.pos[0], sign.pos[1], sign.pos[2]);
      sprite.scale.set(3, 1.1, 1);
      this.group.add(sprite);
    });
  }

  addBox(dim, material) {
    const geometry = new THREE.BoxGeometry(dim.width, dim.height, dim.depth);
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(dim.x, dim.height / 2, dim.z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.userData.blockBullet = true;
    this.group.add(mesh);
    this.meshes.push(mesh);
    this.colliders.push({
      minX: dim.x - dim.width / 2,
      maxX: dim.x + dim.width / 2,
      minZ: dim.z - dim.depth / 2,
      maxZ: dim.z + dim.depth / 2,
      minY: 0,
      maxY: dim.height,
      height: dim.height,
    });
  }

  buildGrid() {
    this.gridSize = 1.4;
    this.gridMinX = -35;
    this.gridMinZ = -22;
    this.cols = Math.round(70 / this.gridSize);
    this.rows = Math.round(44 / this.gridSize);
    this.grid = new Array(this.cols * this.rows).fill(0);
    this.colliders.forEach(collider => {
      if (collider.height <= 0.8) return;
      const minCol = Math.max(0, Math.floor((collider.minX - this.gridMinX) / this.gridSize));
      const maxCol = Math.min(this.cols - 1, Math.floor((collider.maxX - this.gridMinX) / this.gridSize));
      const minRow = Math.max(0, Math.floor((collider.minZ - this.gridMinZ) / this.gridSize));
      const maxRow = Math.min(this.rows - 1, Math.floor((collider.maxZ - this.gridMinZ) / this.gridSize));
      for (let col = minCol; col <= maxCol; col += 1) {
        for (let row = minRow; row <= maxRow; row += 1) this.grid[row * this.cols + col] = 1;
      }
    });
    // Slightly inflate to avoid tight collision.
    const inflated = [];
    for (let row = 0; row < this.rows; row += 1) {
      for (let col = 0; col < this.cols; col += 1) {
        if (!this.grid[row * this.cols + col]) continue;
        inflated.push([col, row]);
      }
    }
    inflated.forEach(([col, row]) => {
      for (let dr = -1; dr <= 1; dr += 1) {
        for (let dc = -1; dc <= 1; dc += 1) {
          const r = row + dr; const c = col + dc;
          if (r >= 0 && r < this.rows && c >= 0 && c < this.cols) this.grid[r * this.cols + c] = 1;
        }
      }
    });
  }

  findPath(start, end) {
    const startCell = this.worldToCell(start);
    const endCell = this.worldToCell(end);
    if (!startCell || !endCell) return [];
    const queue = [startCell];
    const cameFrom = new Map();
    const key = cell => cell.row * this.cols + cell.col;
    cameFrom.set(key(startCell), null);
    let result = null;
    let iterations = 0;
    while (queue.length && iterations < 4500) {
      iterations += 1;
      queue.sort((a, b) => heuristic(a, endCell) - heuristic(b, endCell));
      const current = queue.shift();
      if (current.row === endCell.row && current.col === endCell.col) { result = current; break; }
      const neighbors = [
        { row: current.row + 1, col: current.col },
        { row: current.row - 1, col: current.col },
        { row: current.row, col: current.col + 1 },
        { row: current.row, col: current.col - 1 },
        { row: current.row + 1, col: current.col + 1 },
        { row: current.row + 1, col: current.col - 1 },
        { row: current.row - 1, col: current.col + 1 },
        { row: current.row - 1, col: current.col - 1 },
      ];
      neighbors.forEach(neighbor => {
        if (neighbor.row < 0 || neighbor.row >= this.rows || neighbor.col < 0 || neighbor.col >= this.cols) return;
        if (this.grid[neighbor.row * this.cols + neighbor.col]) return;
        if (cameFrom.has(key(neighbor))) return;
        cameFrom.set(key(neighbor), current);
        queue.push(neighbor);
      });
    }
    if (!result) return [];
    const path = [];
    let current = result;
    while (current) {
      path.unshift(this.cellToWorld(current));
      current = cameFrom.get(key(current));
    }
    return path.slice(1);

    function heuristic(a, b) {
      return Math.abs(a.col - b.col) + Math.abs(a.row - b.row);
    }
  }

  worldToCell(vector) {
    const col = Math.floor((vector.x - this.gridMinX) / this.gridSize);
    const row = Math.floor((vector.z - this.gridMinZ) / this.gridSize);
    if (col < 0 || col >= this.cols || row < 0 || row >= this.rows) return null;
    return { col, row };
  }

  cellToWorld(cell) {
    return new THREE.Vector3(
      this.gridMinX + (cell.col + 0.5) * this.gridSize,
      0,
      this.gridMinZ + (cell.row + 0.5) * this.gridSize,
    );
  }

  randomPointInSite(siteId) {
    const zone = this.siteZones.find(s => s.id === siteId);
    const angle = Math.random() * Math.PI * 2;
    const radius = Math.random() * zone.radius * 0.7;
    return new THREE.Vector3(zone.center.x + Math.cos(angle) * radius, 0, zone.center.y + Math.sin(angle) * radius);
  }

  siteAt(position) {
    return this.siteZones.find(zone => Math.hypot(position.x - zone.center.x, position.z - zone.center.y) <= zone.radius);
  }

  resolveCollision(position, radius = 0.45) {
    let collided = false;
    for (const collider of this.colliders) {
      if (position.y > collider.maxY || position.y + 1.6 < collider.minY) continue;
      const closestX = THREE.MathUtils.clamp(position.x, collider.minX, collider.maxX);
      const closestZ = THREE.MathUtils.clamp(position.z, collider.minZ, collider.maxZ);
      const dx = position.x - closestX;
      const dz = position.z - closestZ;
      const distSq = dx * dx + dz * dz;
      if (distSq < radius * radius) {
        const dist = Math.sqrt(distSq) || 0.0001;
        const push = (radius - dist) / dist;
        position.x += dx * push;
        position.z += dz * push;
        collided = true;
      }
    }
    // Keep inside arena.
    position.x = THREE.MathUtils.clamp(position.x, -34.2, 34.2);
    position.z = THREE.MathUtils.clamp(position.z, -21.2, 21.2);
    return collided;
  }

  raycastTargets() {
    return this.meshes;
  }

  update(dt) {
    this.siteZones.forEach(zone => {
      const pulse = Math.sin(performance.now() * 0.002 + zone.center.x) * 0.08 + 1;
      zone.meshes?.forEach(mesh => mesh.material.opacity = zone.id === 'A' ? 0.28 + pulse * 0.07 : 0.24 + pulse * 0.07);
    });
  }

  dispose() {
    this.group.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) child.material.forEach(m => m.dispose());
        else child.material.dispose();
      }
    });
    this.scene.remove(this.group);
  }
}

function makeCollider(x, z, width, depth, height) {
  return {
    minX: x - width / 2,
    maxX: x + width / 2,
    minZ: z - depth / 2,
    maxZ: z + depth / 2,
    minY: 0,
    maxY: height,
    height,
  };
}

function makeTextTexture(text, color = '#f4f0e8') {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 96;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'rgba(5,8,12,0.72)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = color;
  ctx.lineWidth = 4;
  ctx.strokeRect(6, 6, canvas.width - 12, canvas.height - 12);
  ctx.fillStyle = color;
  ctx.font = '700 44px "Barlow Condensed", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, canvas.width / 2, canvas.height / 2 + 2);
  const texture = new THREE.CanvasTexture(canvas);
  texture.needsUpdate = true;
  return texture;
}

function makeSiteLabel(id, color) {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'rgba(0,0,0,0)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = color;
  ctx.lineWidth = 5;
  ctx.strokeRect(10, 10, 236, 108);
  ctx.fillStyle = color;
  ctx.font = '900 76px "Barlow Condensed", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(`SITE ${id}`, canvas.width / 2, canvas.height / 2 + 22);
  const texture = new THREE.CanvasTexture(canvas);
  texture.needsUpdate = true;
  return texture;
}

export class PlayerHealth {
  constructor(maxHealth = 100) {
    this.maxHealth = maxHealth;
    this.currentHealth = maxHealth;
    this.isAlive = true;
    this.regenTimer = 0;
    this.shield = 0;
    this.shieldTimer = 0;
    this.damageTaken = 0;
    this.lastDamageTime = 0;
  }

  reset(health = this.maxHealth) {
    this.currentHealth = Math.min(health, this.maxHealth);
    this.isAlive = true;
    this.shield = 0;
    this.shieldTimer = 0;
    this.regenTimer = 0;
    this.damageTaken = 0;
    this.lastDamageTime = 0;
  }

  takeDamage(amount, source) {
    if (!this.isAlive) return 0;
    const applied = Math.max(1, Math.round(amount));
    const shieldDamage = Math.min(this.shield, applied);
    this.shield -= shieldDamage;
    const healthDamage = applied - shieldDamage;
    this.currentHealth = Math.max(0, this.currentHealth - healthDamage);
    this.damageTaken += applied;
    this.lastDamageTime = performance.now();
    if (this.currentHealth <= 0) this.die(source);
    return applied;
  }

  heal(amount) {
    if (!this.isAlive) return;
    this.currentHealth = Math.min(this.maxHealth, this.currentHealth + amount);
  }

  addShield(amount, duration) {
    this.shield = Math.max(this.shield, amount);
    this.shieldTimer = duration;
  }

  update(dt) {
    if (!this.isAlive) return;
    if (this.shieldTimer > 0) {
      this.shieldTimer -= dt;
      if (this.shieldTimer <= 0) this.shield = 0;
    }
    if (this.regenTimer > 0) this.regenTimer -= dt;
  }

  die(source) {
    if (!this.isAlive) return;
    this.isAlive = false;
    this.currentHealth = 0;
    if (this.onDeath) this.onDeath(source);
  }
}

import * as THREE from 'three';
import { weapons, getWeapon } from '../data/weapons.js';

export class WeaponController {
  constructor(camera, audio, settings, team = 'attackers') {
    this.camera = camera;
    this.audio = audio;
    this.settings = settings;
    this.team = team;
    this.raycaster = new THREE.Raycaster();
    this.raycaster.far = 120;
    this.slots = {
      primary: this.instantiate(choosePrimary(team)),
      secondary: this.instantiate('pistol'),
    };
    this.currentSlot = 'primary';
    this.fireCooldown = 0;
    this.reloading = false;
    this.reloadTimer = 0;
    this.recoilOffset = 0;
    this.recoilVelocity = 0;
    this.pellets = [];
    this.lastShotTime = 0;
  }

  instantiate(id) {
    const source = getWeapon(id);
    return {
      ...source,
      currentAmmo: source.magazineSize,
      reserveAmmo: source.reserveAmmo,
    };
  }

  get weapon() {
    return this.slots[this.currentSlot];
  }

  switchTo(slot) {
    if (!this.slots[slot] || this.reloading || this.currentSlot === slot) return false;
    this.currentSlot = slot;
    this.fireCooldown = Math.max(this.fireCooldown, 0.24);
    return true;
  }

  canFire() {
    return !this.reloading && this.fireCooldown <= 0 && this.weapon.currentAmmo > 0;
  }

  tryFire(triggerHeld, targets, callbacks = {}) {
    const weapon = this.weapon;
    if (!weapon.automatic && !triggerHeld) return false;
    if (this.fireCooldown > 0 || this.reloading || weapon.currentAmmo <= 0) {
      if (weapon.currentAmmo <= 0 && this.weapon.reserveAmmo > 0) this.reload();
      return false;
    }
    const now = performance.now();
    if (now - this.lastShotTime < weapon.fireRate * 1000) return false;
    this.lastShotTime = now;
    this.fireCooldown = weapon.fireRate;
    weapon.currentAmmo -= 1;
    const origin = this.camera.getWorldPosition(new THREE.Vector3());
    const direction = new THREE.Vector3();
    this.camera.getWorldDirection(direction);
    const shots = weapon.pellets || 1;
    for (let i = 0; i < shots; i += 1) {
      const shotDir = direction.clone();
      const spread = weapon.spread * (this.settings?.get('botDifficulty') === 'elite' ? 0.9 : 1);
      shotDir.x += (Math.random() - 0.5) * spread;
      shotDir.y += (Math.random() - 0.5) * spread;
      shotDir.z += (Math.random() - 0.5) * spread;
      shotDir.normalize();
      this.raycaster.set(origin, shotDir);
      this.raycaster.far = weapon.range;
      const intersects = this.raycaster.intersectObjects(targets, true).filter(intersect => {
        const userData = intersect.object.userData;
        if (userData.blockBullet) return true;
        return userData.isCharacter || userData.isEntity || userData.isBomb || userData.isProp;
      });
      const hit = intersects.find(intersect => intersect.object.userData.blockBullet || intersect.object.userData.isCharacter || intersect.object.userData.isEntity);
      if (hit) {
        const distance = hit.distance;
        const damage = weapon.damage * (1 - Math.min(0.55, distance / weapon.range * 0.5));
        const isHead = hit.object.userData.isHead || hit.object.name === 'head';
        callbacks.onHit?.({
          point: hit.point,
          distance,
          damage: isHead ? damage * weapon.headshotMultiplier : damage,
          isHead,
          object: hit.object,
          userData: hit.object.userData,
        });
      } else {
        callbacks.onMiss?.({ origin, direction: shotDir, distance: weapon.range });
      }
    }
    this.recoilVelocity += weapon.recoil;
    return true;
  }

  reload() {
    const weapon = this.weapon;
    if (this.reloading || weapon.currentAmmo >= weapon.magazineSize || weapon.reserveAmmo <= 0) return false;
    this.reloading = true;
    this.reloadTimer = weapon.reloadTime;
    this.audio.reload();
    return true;
  }

  update(dt) {
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    if (this.reloading) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) {
        const weapon = this.weapon;
        const needed = weapon.magazineSize - weapon.currentAmmo;
        const moved = Math.min(needed, weapon.reserveAmmo);
        weapon.currentAmmo += moved;
        weapon.reserveAmmo -= Math.max(0, moved);
        this.reloading = false;
        this.reloadTimer = 0;
      }
    }
    this.recoilOffset += this.recoilVelocity * dt;
    this.recoilVelocity -= this.recoilOffset * 18 * dt;
    this.recoilOffset = THREE.MathUtils.clamp(this.recoilOffset, -0.12, 0.2);
    this.recoilVelocity *= 0.88;
  }

  resetRound() {
    this.slots.primary = this.instantiate(choosePrimary(this.team));
    this.slots.secondary = this.instantiate('pistol');
    this.currentSlot = 'primary';
    this.reloading = false;
    this.fireCooldown = 0;
    this.reloadTimer = 0;
    this.recoilOffset = 0;
    this.recoilVelocity = 0;
  }
}

function choosePrimary(team) {
  if (team === 'attackers') return 'rifle';
  return 'rifle';
}

export const WEAPON_LIBRARY = weapons;

import * as THREE from 'three';

export class AbilityController {
  constructor(scene, audio, settings) {
    this.scene = scene;
    this.audio = audio;
    this.settings = settings;
    this.character = null;
    this.cooldowns = { active: 0, special: 0 };
    this.activeEffects = [];
    this.temporaryStats = {
      speedMultiplier: 1,
      fireRateMultiplier: 1,
      shield: 0,
      shieldTimer: 0,
      marked: 0,
      scanActive: 0,
    };
  }

  loadCharacter(character) {
    this.character = character;
    this.cooldowns.active = 0;
    this.cooldowns.special = 0;
    this.temporaryStats = {
      speedMultiplier: 1,
      fireRateMultiplier: 1,
      shield: 0,
      shieldTimer: 0,
      marked: 0,
      scanActive: 0,
    };
  }

  resetRound() {
    if (this.character) this.loadCharacter(this.character);
    this.clearEffects();
  }

  clearEffects() {
    this.activeEffects.forEach(effect => {
      if (effect.mesh) {
        this.scene.remove(effect.mesh);
        if (effect.mesh.geometry) effect.mesh.geometry.dispose();
        if (effect.mesh.material) effect.mesh.material.dispose();
      }
    });
    this.activeEffects = [];
  }

  tryActive(entity) {
    if (!this.character || this.cooldowns.active > 0 || !entity.isAlive()) return false;
    const ability = this.character.active;
    this.cooldowns.active = ability.cooldown;
    this.execute(ability, entity, false);
    return true;
  }

  trySpecial(entity) {
    if (!this.character || this.cooldowns.special > 0 || !entity.isAlive()) return false;
    const ability = this.character.special;
    this.cooldowns.special = ability.cooldown;
    this.execute(ability, entity, true);
    return true;
  }

  execute(ability, entity, isSpecial) {
    const type = ability.type;
    const position = entity.mesh?.position.clone() || new THREE.Vector3();
    const forward = new THREE.Vector3();
    if (entity.mesh) {
      forward.set(Math.sin(entity.mesh.rotation.y), 0, Math.cos(entity.mesh.rotation.y));
    } else {
      forward.set(0, 0, 1);
    }
    this.audio.ability(isSpecial ? 'special' : 'normal');
    entity.mesh?.setAction?.('ability', 0);

    switch (type) {
      case 'dash':
        entity.addVelocity(forward.clone().multiplyScalar(11));
        break;
      case 'speedburst':
        this.temporaryStats.speedMultiplier = 1.55;
        this.speedTimer = ability.duration;
        entity.addVelocity(forward.clone().multiplyScalar(3.5));
        break;
      case 'rapidfire':
        this.temporaryStats.fireRateMultiplier = 0.45;
        this.fireRateTimer = ability.duration;
        this.temporaryStats.speedMultiplier = 1.22;
        break;
      case 'heal':
        entity.health.heal(entity.health.maxHealth * 0.42);
        this.spawnPulse(position, entity.team === 'attackers' ? 0xff5b2e : 0x42d9ee, 2.6);
        break;
      case 'shieldaura':
        entity.health.addShield(45, ability.duration);
        if (entity.team) this.auraAllies(entity, ability.duration, 'shield', 45);
        this.spawnRing(position, entity.team === 'attackers' ? 0xff8d3a : 0x42d9ee, 3.2);
        break;
      case 'armoraura':
        this.auraAllies(entity, ability.duration, 'shield', 38);
        this.spawnRing(position, 0x42d9ee, 4);
        break;
      case 'healzone':
        this.addZone(position, ability, entity.team, 'heal', 3.4, 0x74e69a);
        break;
      case 'wall':
        this.addWall(position, forward, entity.team === 'attackers' ? 0xff5b2e : 0x42d9ee, ability.duration);
        break;
      case 'barricadefield':
        this.addWall(position, forward, entity.team === 'attackers' ? 0xff5b2e : 0x42d9ee, ability.duration, 2.4);
        break;
      case 'smokefield':
        this.addZone(position, ability, entity.team, 'smoke', 4.2, 0xb8c4cf);
        break;
      case 'scanpulse':
      case 'widevision':
      case 'marknearest': {
        const enemies = entity.enemies?.() || [];
        let marked = 0;
        enemies.forEach(enemy => {
          if (!enemy.isAlive()) return;
          const distance = enemy.mesh.position.distanceTo(position);
          if (type === 'widevision' || distance < 15) {
            enemy.markedUntil = performance.now() + (type === 'widevision' ? ability.duration * 1000 : 5200);
            marked += 1;
          }
        });
        this.spawnPulse(position, 0xf8c95c, 6.5);
        break;
      }
      case 'slowfield':
        this.addZone(position, ability, entity.team, 'slow', 4.4, 0x8a7cff);
        break;
      case 'gravitywell':
        this.addZone(position, ability, entity.team, 'gravity', 4.6, 0xb07cff);
        break;
      case 'incendiary':
        this.addZone(position, ability, entity.team, 'burn', 4.2, 0xff5b2e);
        break;
      case 'blackout':
        this.addZone(position, ability, entity.team, 'blackout', 5.8, 0x111820);
        break;
      case 'shockstrike': {
        const enemies = entity.enemies?.() || [];
        enemies.forEach(enemy => {
          if (!enemy.isAlive()) return;
          const distance = enemy.mesh.position.distanceTo(position);
          if (distance < 8) enemy.takeDamage(38, entity);
        });
        this.spawnPulse(position, 0x7de7ff, 6.5);
        break;
      }
      case 'concussionmine': {
        const mine = this.addZone(position.clone().add(forward.multiplyScalar(2.2)), { ...ability, duration: 0.5 }, entity.team, 'shock', 3.4, 0xff8c46);
        break;
      }
      case 'decoy': {
        const decoy = new THREE.Mesh(
          new THREE.ConeGeometry(0.55, 1.9, 10),
          new THREE.MeshBasicMaterial({ color: 0x8ef2c7, transparent: true, opacity: 0.4 }),
        );
        decoy.position.copy(position).add(forward.clone().multiplyScalar(2));
        decoy.position.y = 1;
        this.scene.add(decoy);
        this.activeEffects.push({ type: 'decoy', mesh: decoy, duration: ability.duration, timer: ability.duration, team: entity.team, entityId: entity.id });
        break;
      }
      default:
        break;
    }
  }

  auraAllies(entity, duration, kind, amount) {
    const allies = entity.allies?.() || [];
    allies.forEach(ally => {
      if (!ally.isAlive() || ally === entity) return;
      const distance = ally.mesh.position.distanceTo(entity.mesh.position);
      if (distance < 6) {
        if (kind === 'shield') ally.health.addShield(amount, duration);
        if (kind === 'armor') ally.health.addShield(amount, duration);
      }
    });
  }

  addZone(position, ability, team, kind, radius, color) {
    const geometry = new THREE.SphereGeometry(radius, 12, 8);
    const material = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: kind === 'smoke' ? 0.44 : kind === 'blackout' ? 0.5 : 0.16,
    });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.copy(position);
    mesh.position.y = kind === 'smoke' || kind === 'blackout' ? 1.4 : 0.25;
    this.scene.add(mesh);
    const effect = {
      type: kind,
      mesh,
      team,
      radius,
      duration: ability.duration,
      timer: ability.duration,
      damagePerSecond: kind === 'burn' ? 16 : kind === 'shock' ? 32 : 0,
      owner: ability,
    };
    this.activeEffects.push(effect);
    return effect;
  }

  addWall(position, forward, color, duration, width = 4.2) {
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(width, 2.4, 0.42),
      new THREE.MeshLambertMaterial({ color, transparent: true, opacity: 0.52 }),
    );
    const rotationY = Math.atan2(forward.x, forward.z) + Math.PI / 2;
    mesh.position.copy(position).add(forward.clone().multiplyScalar(2.4));
    mesh.position.y = 1.2;
    mesh.rotation.y = rotationY;
    this.scene.add(mesh);
    const effect = { type: 'wall', mesh, duration, timer: duration, team: 'neutral', width };
    this.activeEffects.push(effect);
    return effect;
  }

  spawnPulse(position, color, radius) {
    const geometry = new THREE.RingGeometry(radius - 0.7, radius, 24);
    const material = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.55, side: THREE.DoubleSide });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(position);
    mesh.position.y = 0.06;
    this.scene.add(mesh);
    this.activeEffects.push({ type: 'pulse', mesh, duration: 0.55, timer: 0.55 });
  }

  spawnRing(position, color, radius) {
    const geometry = new THREE.TorusGeometry(radius, 0.08, 6, 24);
    const material = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.5 });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = Math.PI / 2;
    mesh.position.copy(position);
    mesh.position.y = 1.1;
    this.scene.add(mesh);
    this.activeEffects.push({ type: 'ring', mesh, duration: 1.3, timer: 1.3 });
  }

  update(dt, entities = [], map = null) {
    // Temporary stats timers.
    if (this.speedTimer) {
      this.speedTimer -= dt;
      if (this.speedTimer <= 0) this.temporaryStats.speedMultiplier = 1;
    }
    if (this.fireRateTimer) {
      this.fireRateTimer -= dt;
      if (this.fireRateTimer <= 0) this.temporaryStats.fireRateMultiplier = 1;
    }
    this.cooldowns.active = Math.max(0, this.cooldowns.active - dt);
    this.cooldowns.special = Math.max(0, this.cooldowns.special - dt);

    for (let index = this.activeEffects.length - 1; index >= 0; index -= 1) {
      const effect = this.activeEffects[index];
      effect.timer -= dt;
      const lifeRatio = effect.duration > 0 ? Math.max(0, effect.timer / effect.duration) : 0;
      if (effect.mesh) {
        if (effect.type === 'pulse') {
          effect.mesh.material.opacity = lifeRatio * 0.55;
          effect.mesh.scale.setScalar(1 + (1 - lifeRatio) * 0.7);
        } else if (effect.type === 'ring') {
          effect.mesh.material.opacity = lifeRatio * 0.5;
          effect.mesh.rotation.z += dt * 3;
        } else if (effect.type === 'smoke' || effect.type === 'blackout') {
          effect.mesh.material.opacity = Math.min(0.55, lifeRatio * 0.65);
          effect.mesh.scale.setScalar(1 + (1 - lifeRatio) * 0.12);
        } else if (effect.type === 'decoy') {
          effect.mesh.material.opacity = lifeRatio * 0.4;
          effect.mesh.position.y = 1 + Math.sin(performance.now() * 0.004) * 0.05;
        } else if (effect.type === 'burn' || effect.type === 'shock' || effect.type === 'slow' || effect.type === 'gravity' || effect.type === 'heal') {
          effect.mesh.material.opacity = lifeRatio * 0.2;
          effect.mesh.rotation.y += dt * 1.5;
        } else if (effect.type === 'wall') {
          effect.mesh.material.opacity = lifeRatio * 0.5;
        }
      }
      if (effect.type === 'burn' && effect.damagePerSecond) {
        entities.forEach(entity => {
          if (!entity.isAlive() || entity.team === effect.team) return;
          const distance = entity.mesh.position.distanceTo(effect.mesh.position);
          if (distance <= effect.radius) entity.takeDamage(effect.damagePerSecond * dt, { ability: true });
        });
      }
      if (effect.type === 'shock' && effect.damagePerSecond) {
        entities.forEach(entity => {
          if (!entity.isAlive() || entity.team === effect.team) return;
          const distance = entity.mesh.position.distanceTo(effect.mesh.position);
          if (distance <= effect.radius) {
            entity.takeDamage(effect.damagePerSecond * dt, { ability: true });
            entity.slowUntil = performance.now() + 1500;
            entity.visionDisabledUntil = performance.now() + 1200;
          }
        });
      }
      if (effect.type === 'slow' || effect.type === 'gravity') {
        entities.forEach(entity => {
          if (!entity.isAlive() || entity.team === effect.team) return;
          const distance = entity.mesh.position.distanceTo(effect.mesh.position);
          if (distance <= effect.radius) {
            entity.slowUntil = performance.now() + 350;
            if (effect.type === 'gravity') entity.gravityUntil = performance.now() + 350;
          }
        });
      }
      if (effect.type === 'blackout') {
        entities.forEach(entity => {
          if (!entity.isAlive() || entity.team === effect.team) return;
          const distance = entity.mesh.position.distanceTo(effect.mesh.position);
          if (distance <= effect.radius) entity.visionDisabledUntil = performance.now() + 320;
        });
      }
      if (effect.type === 'smoke') {
        entities.forEach(entity => {
          if (!entity.isAlive() || entity.team === effect.team) return;
          const distance = entity.mesh.position.distanceTo(effect.mesh.position);
          if (distance <= effect.radius) entity.accuracyNoise = 0.55;
        });
      }
      if (effect.type === 'heal') {
        entities.forEach(entity => {
          if (!entity.isAlive() || entity.team !== effect.team) return;
          const distance = entity.mesh.position.distanceTo(effect.mesh.position);
          if (distance <= effect.radius) entity.health.heal(14 * dt);
        });
      }
      if (effect.timer <= 0) {
        this.scene.remove(effect.mesh);
        if (effect.mesh.geometry) effect.mesh.geometry.dispose();
        if (effect.mesh.material) effect.mesh.material.dispose();
        this.activeEffects.splice(index, 1);
      }
    }
  }

  status() {
    return {
      activeReady: this.cooldowns.active <= 0,
      specialReady: this.cooldowns.special <= 0,
      activeCooldown: this.cooldowns.active,
      specialCooldown: this.cooldowns.special,
      active: this.character?.active,
      special: this.character?.special,
      speedMultiplier: this.temporaryStats.speedMultiplier,
      fireRateMultiplier: this.temporaryStats.fireRateMultiplier,
    };
  }
}

import * as THREE from 'three';
import { PlayerHealth } from './health.js';
import { WeaponController } from './weaponController.js';
import { createCharacterMesh } from '../three/characterMesh.js';

export class PlayerController {
  constructor({ camera, scene, settings, audio, map, character, team, id = 'player' }) {
    this.camera = camera;
    this.scene = scene;
    this.settings = settings;
    this.audio = audio;
    this.map = map;
    this.character = character;
    this.team = team;
    this.id = id;
    this.isPlayer = true;
    this.health = new PlayerHealth(character.health);
    this.mesh = createCharacterMesh(character, settings.get('selectedSkin'));
    this.mesh.visible = false;
    this.mesh.userData.entityId = this.id;
    this.mesh.userData.isEntity = true;
    this.mesh.userData.isPlayer = true;
    this.scene.add(this.mesh);
    this.velocity = new THREE.Vector3();
    this.horizontalVelocity = new THREE.Vector3();
    this.grounded = true;
    this.gravity = 21;
    this.jumpForce = character.movement.jump;
    this.walkSpeed = character.movement.walk;
    this.runSpeed = character.movement.run;
    this.momentumUntil = 0;
    this.accuracyNoise = 0;
    this.slowUntil = 0;
    this.visionDisabledUntil = 0;
    this.gravityUntil = 0;
    this.markedUntil = 0;
    this.deathTime = 0;
    this.yaw = team === 'attackers' ? Math.PI : 0;
    this.pitch = 0;
    this.movementInput = new THREE.Vector2();
    this.abilityController = null;
    this.buildViewModel();
    this.setSpawn(team === 'attackers' ? new THREE.Vector3(0, 0, 18) : new THREE.Vector3(0, 0, -18));
    this.health.onDeath = () => this.handleDeath();
  }

  buildViewModel() {
    this.viewModel = new THREE.Group();
    this.camera.add(this.viewModel);
    this.buildGun('rifle');
    this.viewModel.position.set(0.24, -0.24, -0.45);
    this.viewModel.rotation.set(0.04, -0.1, 0.02);
  }

  buildGun(type = 'rifle') {
    this.clearChildren(this.viewModel);
    const material = new THREE.MeshLambertMaterial({ color: 0x22272e });
    const accentMaterial = new THREE.MeshLambertMaterial({ color: 0x1c2a35, emissive: 0x2a4a5c, emissiveIntensity: 0.35 });
    const group = new THREE.Group();
    const barrelLength = type === 'pistol' ? 0.14 : type === 'sniper' ? 0.5 : 0.28;
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, barrelLength, 7), material);
    barrel.rotation.x = Math.PI / 2;
    barrel.position.z = -barrelLength / 2 - 0.05;
    group.add(barrel);
    const body = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.07, type === 'pistol' ? 0.12 : 0.24), material);
    body.position.z = -0.02;
    group.add(body);
    const magazine = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.09, 0.045), material);
    magazine.position.set(0, -0.065, type === 'pistol' ? 0.02 : -0.02);
    group.add(magazine);
    const handle = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.08, 0.05), material);
    handle.position.set(0, -0.05, 0.07);
    handle.rotation.x = -0.15;
    group.add(handle);
    const glow = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.014, 0.014), accentMaterial);
    glow.position.set(0, 0.04, -0.08);
    group.add(glow);
    const stockLength = type === 'pistol' ? 0 : 0.1;
    if (stockLength > 0) {
      const stock = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.05, stockLength), material);
      stock.position.set(0, -0.02, 0.12);
      group.add(stock);
    }
    this.viewModel.add(group);
    this.gunGroup = group;
  }

  clearChildren(object) {
    while (object.children.length) {
      const child = object.children.pop();
      child.geometry?.dispose?.();
      child.material?.dispose?.();
    }
  }

  setSpawn(position) {
    this.mesh.position.copy(position);
    this.mesh.position.y = 0;
    this.velocity.set(0, 0, 0);
    this.horizontalVelocity.set(0, 0, 0);
    this.grounded = true;
    this.yaw = this.team === 'attackers' ? Math.PI : 0;
    this.pitch = 0;
    this.mesh.rotation.set(0, this.yaw, 0);
    this.updateCamera(0);
  }

  addVelocity(vector) {
    this.velocity.add(vector);
  }

  isAlive() {
    return this.health.isAlive;
  }

  enemies() {
    return this.enemiesList || [];
  }

  allies() {
    return this.alliesList || [];
  }

  takeDamage(amount, source = null) {
    if (!this.health.isAlive) return 0;
    let applied = amount;
    const passive = this.character.passive?.flags || {};
    if (passive.damageReduction) applied *= 1 - passive.damageReduction;
    if (passive.firstHitReduce && !this.firstHitUsed) {
      applied *= 0.62;
      this.firstHitUsed = true;
    }
    const result = this.health.takeDamage(applied, source);
    if (this.character.passive.flags?.momentumOnDamage && result > 0) {
      this.momentumUntil = performance.now() + (this.character.passive.flags.momentumDuration * 1000);
    }
    return result;
  }

  handleDeath() {
    this.mesh.visible = true;
    this.mesh.setAction('death', 0);
    this.deathTime = performance.now();
    this.health.isAlive = false;
  }

  resetRound() {
    this.health.reset(this.character.health);
    this.firstHitUsed = false;
    this.mesh.visible = false;
    this.mesh.setAction('idle', 0);
    this.mesh.rotation.set(0, this.team === 'attackers' ? Math.PI : 0, 0);
    this.mesh.position.set(0, 0, this.team === 'attackers' ? 18 : -18);
    this.abilityController?.resetRound();
    this.weapon?.resetRound();
    this.deathTime = 0;
    this.momentumUntil = 0;
    this.slowUntil = 0;
    this.visionDisabledUntil = 0;
    this.accuracyNoise = 0;
    this.markedUntil = 0;
  }

  update(dt, input) {
    const move = new THREE.Vector3(input.moveX || 0, 0, input.moveZ || 0);
    if (move.lengthSq() > 1) move.normalize();
    const forward = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    const right = new THREE.Vector3(forward.z, 0, -forward.x);
    const desired = new THREE.Vector3();
    desired.addScaledVector(forward, -move.z);
    desired.addScaledVector(right, move.x);
    const moveLength = Math.min(1, desired.length());
    if (moveLength > 0) desired.normalize();
    let speed = input.sprint ? this.runSpeed : this.walkSpeed;
    if (this.momentumUntil > performance.now()) speed *= 1.12;
    if (this.slowUntil > performance.now()) speed *= 0.55;
    if (this.abilityController?.temporaryStats.speedMultiplier) speed *= this.abilityController.temporaryStats.speedMultiplier;
    if (this.gravityUntil > performance.now()) speed *= 0.4;
    if (this.health.isAlive) {
      this.horizontalVelocity.lerp(desired.multiplyScalar(speed * moveLength), 1 - Math.pow(0.0015, dt));
    } else {
      this.horizontalVelocity.multiplyScalar(0.9);
    }

    // Gravity and jump.
    if (this.health.isAlive && this.grounded && input.jump) {
      this.velocity.y = this.jumpForce;
      this.grounded = false;
      this.audio.jump();
    }
    this.velocity.y -= this.gravity * dt;
    this.mesh.position.addScaledVector(this.horizontalVelocity, dt);
    this.mesh.position.addScaledVector(this.velocity, dt);

    if (this.mesh.position.y <= 0) {
      this.mesh.position.y = 0;
      this.velocity.y = 0;
      this.grounded = true;
    }
    this.map.resolveCollision(this.mesh.position, 0.5);

    const moveSpeed = Math.hypot(this.horizontalVelocity.x, this.horizontalVelocity.z);
    this.mesh.rotation.y = this.yaw;
    this.mesh.animate(dt, moveSpeed, this.grounded, this.health.isAlive);
    if (moveSpeed > 1.4 && this.grounded) {
      this.footstepTimer = (this.footstepTimer || 0) - dt;
      if (this.footstepTimer <= 0) {
        this.audio.footstep(moveSpeed);
        this.footstepTimer = moveSpeed > this.runSpeed * 0.85 ? 0.34 : 0.52;
      }
    }

    if (this.character.passive.flags?.passiveRegen && this.health.isAlive) {
      const sinceDamage = performance.now() - this.health.lastDamageTime;
      if (sinceDamage > (this.character.passive.flags.regenDelay * 1000)) {
        this.health.heal(this.character.passive.flags.regenPerSecond * dt);
      }
    }

    this.weapon?.update(dt * (this.abilityController?.temporaryStats.fireRateMultiplier || 1));
    this.updateCamera(dt);
    this.updateViewModel(dt, input, moveSpeed);
  }

  updateCamera(dt) {
    const eyeHeight = 1.62 + Math.sin(performance.now() * 0.006) * 0.012 * (this.horizontalVelocity.length() > 0.6 ? 1 : 0);
    this.camera.position.set(this.mesh.position.x, this.mesh.position.y + eyeHeight, this.mesh.position.z);
    this.camera.rotation.set(this.pitch, this.yaw, 0, 'YXZ');
    const fov = this.settings.get('fov');
    if (this.camera.fov !== fov) {
      this.camera.fov = fov;
      this.camera.updateProjectionMatrix();
    }
  }

  updateViewModel(dt, input, moveSpeed) {
    if (!this.viewModel) return;
    const swayX = Math.sin(performance.now() * 0.003) * 0.004;
    const swayY = Math.cos(performance.now() * 0.004) * 0.005;
    const bob = moveSpeed > 0.4 ? Math.sin(performance.now() * 0.02) * 0.008 : 0;
    const recoil = this.weapon?.recoilOffset || 0;
    this.viewModel.position.set(0.24 + swayX, -0.24 + swayY + bob, -0.45 + recoil * 0.35);
    this.viewModel.rotation.set(0.04 + recoil * 0.3, -0.1 + swayX * 2, 0.02);
    if (this.weapon?.reloading) this.viewModel.rotation.z = Math.sin(performance.now() * 0.012) * 0.18;
    else this.viewModel.rotation.z = THREE.MathUtils.lerp(this.viewModel.rotation.z, 0, dt * 7);
    if (this.weapon && this.weapon.currentSlot !== this.lastSlot) {
      this.lastSlot = this.weapon.currentSlot;
      this.buildGun(this.weapon.currentSlot);
    }
  }

  eyePosition() {
    return new THREE.Vector3(this.mesh.position.x, this.mesh.position.y + 1.55, this.mesh.position.z);
  }

  dispose() {
    this.clearChildren(this.viewModel);
    this.camera.remove(this.viewModel);
    this.scene.remove(this.mesh);
  }
}

import * as THREE from 'three';
import { PlayerHealth } from '../player/health.js';
import { createCharacterMesh } from '../three/characterMesh.js';
import { getWeapon } from '../data/weapons.js';

const DIFFICULTY = {
  recruit: { accuracy: 0.42, reaction: 0.42, viewDistance: 26, fireRateMultiplier: 1.35, aggression: 0.7 },
  veteran: { accuracy: 0.66, reaction: 0.26, viewDistance: 32, fireRateMultiplier: 1.15, aggression: 0.9 },
  elite: { accuracy: 0.82, reaction: 0.14, viewDistance: 38, fireRateMultiplier: 0.95, aggression: 1.15 },
};

export class BotController {
  constructor({ scene, map, audio, character, team, difficulty = 'veteran', id, settings }) {
    this.scene = scene;
    this.map = map;
    this.audio = audio;
    this.character = character;
    this.team = team;
    this.id = id;
    this.isPlayer = false;
    this.settings = settings;
    this.difficulty = DIFFICULTY[difficulty] || DIFFICULTY.veteran;
    this.health = new PlayerHealth(character.health);
    this.mesh = createCharacterMesh(character, Math.floor(Math.random() * character.skins.length));
    this.mesh.userData.entityId = id;
    this.mesh.userData.isEntity = true;
    this.mesh.userData.isBot = true;
    this.mesh.userData.isCharacter = true;
    scene.add(this.mesh);
    this.velocity = new THREE.Vector3();
    this.speed = character.movement.walk;
    this.runSpeed = character.movement.run;
    this.grounded = true;
    this.yaw = 0;
    this.weapon = { ...getWeapon(team === 'attackers' ? 'rifle' : 'rifle'), currentAmmo: getWeapon('rifle').magazineSize, reserveAmmo: 90 };
    this.fireCooldown = 0;
    this.reloading = false;
    this.reloadTimer = 0;
    this.target = null;
    this.path = [];
    this.pathTimer = 0;
    this.objective = null;
    this.bombRole = 'none';
    this.patrolIndex = Math.floor(Math.random() * 4);
    this.repathTimer = 0;
    this.momentum = 0;
    this.accuracyNoise = 0;
    this.slowUntil = 0;
    this.visionDisabledUntil = 0;
    this.gravityUntil = 0;
    this.markedUntil = 0;
    this.spawn = new THREE.Vector3();
    this.raycaster = new THREE.Raycaster();
    this.lastPosition = new THREE.Vector3();
    this.stuckTimer = 0;
    this.footstepTimer = 0;
    this.plantTimer = 0;
    this.defuseTimer = 0;
  }

  setSpawn(position, yaw = 0) {
    this.mesh.position.copy(position);
    this.mesh.position.y = 0;
    this.spawn.copy(position);
    this.yaw = yaw;
    this.mesh.rotation.y = yaw;
    this.velocity.set(0, 0, 0);
    this.path = [];
    this.target = null;
  }

  isAlive() {
    return this.health.isAlive;
  }

  enemies() {
    return this.enemiesList || [];
  }

  allies() {
    return this.alliesList || [];
  }

  addVelocity(vector) {
    this.velocity.add(vector);
  }

  takeDamage(amount, source = null) {
    if (!this.health.isAlive) return 0;
    let applied = amount;
    if (this.character.passive.flags?.damageReduction) applied *= 1 - this.character.passive.flags.damageReduction;
    if (this.character.passive.flags?.firstHitReduce && !this.firstHitUsed) {
      applied *= 0.62;
      this.firstHitUsed = true;
    }
    const result = this.health.takeDamage(applied, source);
    if (result > 0 && !this.target && source && source.mesh) this.setTarget(source);
    return result;
  }

  setTarget(entity) {
    this.target = entity;
    this.targetMemory = performance.now();
  }

  resetRound() {
    this.health.reset(this.character.health);
    this.firstHitUsed = false;
    this.mesh.visible = true;
    this.mesh.setAction('idle', 0);
    this.mesh.position.copy(this.spawn);
    this.mesh.rotation.y = this.yaw;
    this.weapon.currentAmmo = this.weapon.magazineSize;
    this.weapon.reserveAmmo = 90;
    this.reloading = false;
    this.reloadTimer = 0;
    this.fireCooldown = 0;
    this.target = null;
    this.path = [];
    this.plantTimer = 0;
    this.defuseTimer = 0;
    this.bombRole = 'none';
    this.slowUntil = 0;
    this.visionDisabledUntil = 0;
    this.accuracyNoise = 0;
    this.markedUntil = 0;
  }

  update(dt, game) {
    if (!this.health.isAlive) {
      this.mesh.animate(dt, 0, false, false);
      return;
    }
    this.fireCooldown -= dt;
    this.pathTimer -= dt;
    this.repathTimer -= dt;

    // Target selection.
    this.selectTarget(game);
    if (this.target && !this.target.isAlive()) this.target = null;
    if (this.target && performance.now() - (this.targetMemory || 0) > 4000 && !this.hasLineOfSight(this.target)) this.target = null;

    // Objectives.
    let desiredPosition = null;
    if (this.team === 'attackers') desiredPosition = this.attackObjective(game);
    else desiredPosition = this.defendObjective(game);

    // Movement.
    if (desiredPosition) this.moveTowards(dt, desiredPosition);
    else this.moveStrafe(dt);

    // Handle actions.
    if (this.team === 'attackers' && this.bombRole === 'carrier' && !game.bomb.planted && game.round.state === 'active') {
      const site = this.map.siteAt(this.mesh.position);
      if (site && !this.target && !this.hasEnemyNear(game, 10)) {
        this.plantTimer += dt;
        this.mesh.setAction('plantBomb', 0);
        if (this.plantTimer > 1.6) {
          this.plantTimer = 0;
          game.bomb.plant(this);
        }
      } else if (this.plantTimer > 0) {
        this.plantTimer = 0;
      }
    }

    if (this.team === 'defenders' && game.bomb.state === 'planted' && game.round.state === 'bombPlanted') {
      const distance = this.mesh.position.distanceTo(game.bomb.position);
      if (distance < 2.4) {
        this.defuseTimer += dt;
        this.mesh.setAction('defuseBomb', 0);
        if (this.defuseTimer > 2.8) {
          this.defuseTimer = 0;
          game.bomb.startDefuse(this, true);
        }
      } else if (this.defuseTimer > 0) this.defuseTimer = 0;
    }

    // Combat.
    if (this.target) this.engageTarget(dt, game);
    else this.fireCooldown = Math.max(this.fireCooldown, 0.06);

    // Movement animation.
    const moveSpeed = Math.hypot(this.velocity.x, this.velocity.z);
    this.mesh.rotation.y = this.yaw;
    this.mesh.position.addScaledVector(this.velocity, dt);
    this.velocity.y -= 21 * dt;
    if (this.mesh.position.y <= 0) {
      this.mesh.position.y = 0;
      this.velocity.y = 0;
      this.grounded = true;
    }
    this.map.resolveCollision(this.mesh.position, 0.5);
    this.mesh.animate(dt, moveSpeed, true, true);
    if (moveSpeed > 1.2) {
      this.footstepTimer -= dt;
      if (this.footstepTimer <= 0) {
        const player = game.player;
        const distance = player.mesh.position.distanceTo(this.mesh.position);
        if (distance < 22 && !(this.character.passive.flags?.footstepNoiseReduction)) this.audio.footstep(distance);
        this.footstepTimer = 0.42;
      }
    }
  }

  selectTarget(game) {
    const eye = this.eyePosition();
    let best = null;
    let bestScore = Infinity;
    const enemies = this.enemiesList || [];
    enemies.forEach(enemy => {
      if (!enemy.isAlive()) return;
      const enemyEye = enemy.eyePosition?.() || enemy.mesh.position.clone().setY(enemy.mesh.position.y + 1.5);
      const distance = eye.distanceTo(enemyEye);
      const detectionRange = this.difficulty.viewDistance * (enemy.character.passive.flags?.detectionNoise ? 0.72 : 1);
      if (distance > detectionRange) return;
      const directionToEnemy = enemyEye.clone().sub(eye).normalize();
      const viewDirection = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
      const angle = viewDirection.dot(directionToEnemy);
      if (angle < 0.35) return;
      if (!this.hasLineOfSight(enemy)) return;
      const score = distance / (enemy.isPlayer ? 0.9 : 1);
      if (score < bestScore) { bestScore = score; best = enemy; }
    });
    if (best && (!this.target || best !== this.target)) {
      if (!this.target || performance.now() - (this.targetMemory || 0) > this.difficulty.reaction * 1000) {
        this.setTarget(best);
      }
    }
  }

  hasLineOfSight(target) {
    const origin = this.eyePosition();
    const targetEye = target.eyePosition?.() || target.mesh.position.clone().setY(target.mesh.position.y + 1.5);
    const direction = targetEye.clone().sub(origin).normalize();
    const distance = origin.distanceTo(targetEye);
    this.raycaster.set(origin, direction);
    this.raycaster.far = distance - 0.4;
    const blockers = this.map.raycastTargets();
    const intersections = this.raycaster.intersectObjects(blockers, false);
    return intersections.length === 0;
  }

  hasEnemyNear(game, radius) {
    const enemies = this.enemiesList || [];
    return enemies.some(enemy => enemy.isAlive() && enemy.mesh.position.distanceTo(this.mesh.position) < radius);
  }

  attackObjective(game) {
    const bomb = game.bomb;
    if (bomb.state === 'planted') {
      if (this.mesh.position.distanceTo(bomb.position) > 6) return bomb.position;
      return null;
    }
    const targetSite = game.attackSite || 'A';
    const siteCenter = this.map.siteZones.find(site => site.id === targetSite).center;
    if (!this.bombRole || this.bombRole === 'none') {
      const aliveAttackers = (this.alliesList || []).filter(entity => entity.isAlive());
      const carrier = aliveAttackers.find(entity => entity.bombRole === 'carrier');
      if (carrier) {
        if (carrier !== this && carrier.mesh.position.distanceTo(this.mesh.position) > 4.5) return carrier.mesh.position;
      }
    }
    if (this.bombRole === 'carrier') {
      const inSite = this.map.siteAt(this.mesh.position);
      if (!inSite || inSite.id !== targetSite) {
        const sitePos = new THREE.Vector3(siteCenter.x, 0, siteCenter.y);
        return sitePos;
      }
      if (this.hasEnemyNear(game, 12)) return null;
      return null;
    }
    // Support the carrier.
    const sitePos = new THREE.Vector3(siteCenter.x, 0, siteCenter.y);
    if (this.mesh.position.distanceTo(sitePos) > 9) return sitePos;
    return null;
  }

  defendObjective(game) {
    const bomb = game.bomb;
    if (bomb.state === 'planted' || bomb.state === 'defusing') {
      const distance = this.mesh.position.distanceTo(bomb.position);
      if (distance > 2.4) return bomb.position;
      return null;
    }
    const assignedSite = game.defendSite || 'A';
    const siteCenter = this.map.siteZones.find(site => site.id === assignedSite).center;
    const patrolPoints = this.map.patrolPoints.defenders;
    const patrolPoint = patrolPoints[(this.patrolIndex + Math.floor(performance.now() / 20000)) % patrolPoints.length];
    const atSite = Math.hypot(this.mesh.position.x - siteCenter.x, this.mesh.position.z - siteCenter.y) < 8;
    if (!atSite && Math.random() < 0.9) return new THREE.Vector3(siteCenter.x, 0, siteCenter.y);
    if (this.mesh.position.distanceTo(patrolPoint) < 1.4) {
      this.patrolIndex = (this.patrolIndex + 1) % patrolPoints.length;
      return patrolPoints[this.patrolIndex];
    }
    return patrolPoint;
  }

  moveTowards(dt, target) {
    const distance = this.mesh.position.distanceTo(target);
    if (distance < 1.4) { this.velocity.multiplyScalar(0.4); return; }
    if (this.pathTimer <= 0 || this.path.length === 0) {
      this.path = this.map.findPath(this.mesh.position, target);
      this.pathTimer = 0.65;
    }
    const nextPoint = this.path.length ? this.path[0] : target;
    const toTarget = nextPoint.clone().sub(this.mesh.position);
    toTarget.y = 0;
    const localDistance = toTarget.length();
    if (localDistance < 0.6 && this.path.length) this.path.shift();
    const desired = toTarget.normalize().multiplyScalar(this.runSpeed * (this.target ? 0.68 : 1));
    if (this.slowUntil > performance.now()) desired.multiplyScalar(0.5);
    if (this.gravityUntil > performance.now()) desired.multiplyScalar(0.4);
    this.velocity.lerp(desired, 1 - Math.pow(0.0009, dt));
    const targetYaw = Math.atan2(desired.x, desired.z);
    this.yaw = THREE.MathUtils.lerpAngle(this.yaw, targetYaw, Math.min(1, dt * 6));
    this.detectStuck(dt, target);
  }

  moveStrafe(dt) {
    const strafe = Math.sin(performance.now() * 0.001 + this.mesh.position.x) * 0.4;
    const desired = new THREE.Vector3(strafe, 0, Math.cos(performance.now() * 0.0012 + this.mesh.position.z) * 0.2);
    this.velocity.lerp(desired.multiplyScalar(this.walkSpeed * 0.3), 1 - Math.pow(0.001, dt));
    if (this.target) {
      const targetPos = this.target.mesh.position;
      const toTarget = targetPos.clone().sub(this.mesh.position);
      this.yaw = THREE.MathUtils.lerpAngle(this.yaw, Math.atan2(toTarget.x, toTarget.z), Math.min(1, dt * 5));
    }
  }

  detectStuck(dt, target) {
    const moved = this.mesh.position.distanceTo(this.lastPosition);
    if (moved < 0.015 && this.velocity.lengthSq() > 0.2) {
      this.stuckTimer += dt;
      if (this.stuckTimer > 0.5) {
        this.stuckTimer = 0;
        this.path = [];
        this.pathTimer = 0;
        const random = new THREE.Vector3((Math.random() - 0.5) * 2, 0, (Math.random() - 0.5) * 2);
        this.velocity.add(random.multiplyScalar(3.2));
        this.map.resolveCollision(this.mesh.position, 0.5);
      }
    } else this.stuckTimer = 0;
    this.lastPosition.copy(this.mesh.position);
  }

  engageTarget(dt, game) {
    const target = this.target;
    if (!target || !target.isAlive()) return;
    const origin = this.eyePosition();
    const targetPos = target.eyePosition?.() || target.mesh.position.clone().setY(target.mesh.position.y + 1.4);
    const toTarget = targetPos.clone().sub(origin);
    const distance = toTarget.length();
    if (distance > this.weapon.range) return;
    if (!this.hasLineOfSight(target)) return;
    const desiredYaw = Math.atan2(toTarget.x, toTarget.z);
    this.yaw = THREE.MathUtils.lerpAngle(this.yaw, desiredYaw, Math.min(1, dt * 7));
    if (this.reloading) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) {
        this.weapon.currentAmmo = this.weapon.magazineSize;
        this.reloading = false;
      }
      return;
    }
    if (this.weapon.currentAmmo <= 0) {
      this.weapon.currentAmmo = 0;
      this.reloading = true;
      this.reloadTimer = this.weapon.reloadTime;
      this.audio.reload();
      return;
    }
    if (this.fireCooldown > 0) return;
    this.fireCooldown = this.weapon.fireRate * this.difficulty.fireRateMultiplier;
    this.weapon.currentAmmo -= 1;
    this.mesh.setAction('shoot', 0);
    const accuracy = this.difficulty.accuracy * (this.character.passive.flags?.stationaryAccuracy && this.velocity.lengthSq() < 0.2 ? 1.25 : 1) * (1 - this.accuracyNoise * 0.7);
    const hitChance = THREE.MathUtils.clamp(accuracy * (1 - Math.min(0.7, distance / this.weapon.range * 0.75)), 0.08, 0.94);
    const hit = Math.random() < hitChance;
    game.spawnTracer(origin, targetPos, hit);
    this.audio.shot(this.weapon.sound, origin.distanceTo(game.player.mesh.position));
    if (hit) {
      const damage = this.weapon.damage * (1 - Math.min(0.5, distance / this.weapon.range * 0.45));
      const isHead = Math.random() < 0.16;
      const finalDamage = isHead ? damage * this.weapon.headshotMultiplier : damage;
      target.takeDamage(finalDamage, this);
    }
  }

  eyePosition() {
    return new THREE.Vector3(this.mesh.position.x, this.mesh.position.y + 1.55, this.mesh.position.z);
  }

  dispose() {
    this.scene.remove(this.mesh);
    this.mesh.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  }
}

import * as THREE from 'three';

export const BombState = {
  NOT_PLANTED: 'notPlanted',
  PLANTING: 'planting',
  PLANTED: 'planted',
  DEFUSING: 'defusing',
  DEFUSED: 'defused',
  EXPLODED: 'exploded',
};

export class BombController {
  constructor({ scene, map, audio }) {
    this.scene = scene;
    this.map = map;
    this.audio = audio;
    this.state = BombState.NOT_PLANTED;
    this.position = new THREE.Vector3();
    this.site = null;
    this.timer = 35;
    this.plantProgress = 0;
    this.defuseProgress = 0;
    this.entity = null;
    this.plantingEntity = null;
    this.defusingEntity = null;
    this.isBotAction = false;
    this.lastBeep = 0;
    this.visible = false;
    this.createMesh();
    this.hide();
  }

  createMesh() {
    this.group = new THREE.Group();
    const caseMesh = new THREE.Mesh(
      new THREE.BoxGeometry(0.7, 0.3, 0.45),
      new THREE.MeshLambertMaterial({ color: 0x2b333c }),
    );
    caseMesh.position.y = 0.15;
    caseMesh.castShadow = true;
    const light = new THREE.Mesh(
      new THREE.SphereGeometry(0.07, 8, 6),
      new THREE.MeshBasicMaterial({ color: 0xff344b }),
    );
    light.position.set(0, 0.28, 0);
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.18, 6), new THREE.MeshBasicMaterial({ color: 0xdfe3e8 }));
    antenna.position.set(0.25, 0.32, 0);
    const pulse = new THREE.Mesh(
      new THREE.RingGeometry(0.8, 1.1, 26),
      new THREE.MeshBasicMaterial({ color: 0xff344b, transparent: true, opacity: 0.5, side: THREE.DoubleSide }),
    );
    pulse.rotation.x = -Math.PI / 2;
    pulse.position.y = 0.04;
    this.group.add(caseMesh, light, antenna, pulse);
    this.lightMesh = light;
    this.pulseMesh = pulse;
    this.group.userData.isBomb = true;
    this.scene.add(this.group);
  }

  resetRound() {
    this.state = BombState.NOT_PLANTED;
    this.position.set(0, 0, 0);
    this.site = null;
    this.timer = 35;
    this.plantProgress = 0;
    this.defuseProgress = 0;
    this.entity = null;
    this.plantingEntity = null;
    this.defusingEntity = null;
    this.isBotAction = false;
    this.hide();
  }

  hide() {
    this.group.visible = false;
    this.visible = false;
  }

  show(position) {
    this.group.position.copy(position);
    this.group.position.y = 0;
    this.group.visible = true;
    this.visible = true;
  }

  canPlant(entity, site) {
    if (!entity || !entity.isAlive() || entity.team !== 'attackers') return false;
    if (this.state !== BombState.NOT_PLANTED && this.state !== BombState.PLANTING) return false;
    const currentSite = this.map.siteAt(entity.mesh.position);
    if (!currentSite) return false;
    if (site && currentSite.id !== site) return false;
    return true;
  }

  startPlant(entity, bot = false) {
    if (!this.canPlant(entity)) return false;
    this.state = BombState.PLANTING;
    this.site = this.map.siteAt(entity.mesh.position).id;
    this.position.copy(entity.mesh.position);
    this.position.y = 0;
    this.plantProgress = 0;
    this.plantingEntity = entity;
    this.isBotAction = bot;
    this.audio.plant();
    return true;
  }

  updatePlant(dt, stillHolding = true) {
    if (this.state !== BombState.PLANTING) return false;
    if (!stillHolding || !this.plantingEntity?.isAlive() || this.map.siteAt(this.plantingEntity.mesh.position)?.id !== this.site) {
      this.state = BombState.NOT_PLANTED;
      this.plantProgress = 0;
      this.plantingEntity = null;
      this.site = null;
      return false;
    }
    const speed = this.plantingEntity.character?.passive.flags?.bombSpeed || 1;
    this.plantProgress += dt * (1 / speed);
    if (this.plantProgress >= 3.2) {
      this.completePlant();
      return true;
    }
    return false;
  }

  completePlant() {
    this.state = BombState.PLANTED;
    this.timer = 35;
    this.plantProgress = 0;
    this.show(this.position);
    this.audio.bombBeep(1);
  }

  canDefuse(entity) {
    if (!entity || !entity.isAlive() || entity.team !== 'defenders') return false;
    if (this.state !== BombState.PLANTED && this.state !== BombState.DEFUSING) return false;
    return entity.mesh.position.distanceTo(this.position) < 3.2;
  }

  startDefuse(entity, bot = false) {
    if (!this.canDefuse(entity)) return false;
    this.state = BombState.DEFUSING;
    this.defusingEntity = entity;
    this.defuseProgress = 0;
    this.isBotAction = bot;
    this.audio.defuse();
    return true;
  }

  updateDefuse(dt, stillHolding = true) {
    if (this.state !== BombState.DEFUSING) return false;
    if (!stillHolding || !this.defusingEntity?.isAlive() || this.defusingEntity.mesh.position.distanceTo(this.position) > 3.4) {
      this.state = BombState.PLANTED;
      this.defuseProgress = 0;
      this.defusingEntity = null;
      return false;
    }
    const speed = this.defusingEntity.character?.passive.flags?.bombSpeed || 1;
    this.defuseProgress += dt * (1 / speed);
    if (this.defuseProgress >= 5) {
      this.defused();
      return true;
    }
    return false;
  }

  defused() {
    this.state = BombState.DEFUSED;
    this.defuseProgress = 0;
    this.defusingEntity = null;
    this.audio.defuse();
  }

  explode() {
    this.state = BombState.EXPLODED;
    this.audio.explosion();
    this.hide();
  }

  update(dt) {
    if (this.state === BombState.PLANTED || this.state === BombState.DEFUSING) {
      this.timer -= dt;
      const beepInterval = this.timer < 8 ? 0.24 : this.timer < 16 ? 0.45 : 0.85;
      this.lastBeep -= dt;
      if (this.lastBeep <= 0) {
        this.audio.bombBeep(this.timer < 8 ? 1.6 : 1);
        this.lastBeep = beepInterval;
      }
      this.lightMesh.material.color.setHex(Math.floor(performance.now() / 180) % 2 ? 0xff344b : 0x88121e);
      const pulseScale = 1 + Math.sin(performance.now() * 0.008) * 0.1;
      this.pulseMesh.scale.setScalar(pulseScale);
      this.pulseMesh.material.opacity = 0.28 + Math.sin(performance.now() * 0.006) * 0.15;
      if (this.timer <= 0) {
        this.explode();
        return true;
      }
    } else {
      this.lightMesh.material.color.setHex(0xff344b);
      this.pulseMesh.scale.setScalar(1);
    }
    return false;
  }

  status() {
    return {
      state: this.state,
      timer: this.timer,
      site: this.site,
      plantProgress: this.plantProgress,
      defuseProgress: this.defuseProgress,
      position: this.position.clone(),
    };
  }
}

import { BombState } from '../objectives/bombController.js';

export const RoundState = {
  WAITING_FOR_PLAYERS: 'waitingForPlayers',
  PREPARING: 'preparingRound',
  STARTING: 'roundStarting',
  ACTIVE: 'roundActive',
  BOMB_PLANTED: 'bombPlanted',
  ENDING: 'roundEnding',
  MATCH_FINISHED: 'matchFinished',
};

export class RoundManager {
  constructor({ teamManager, bomb, audio, settings }) {
    this.teamManager = teamManager;
    this.bomb = bomb;
    this.audio = audio;
    this.settings = settings;
    this.state = RoundState.WAITING_FOR_PLAYERS;
    this.roundNumber = 0;
    this.roundTarget = settings.get('roundTarget');
    this.timer = 0;
    this.roundTime = 95;
    this.prepTime = 3.2;
    this.endDelay = 3.4;
    this.onStateChange = null;
    this.onRoundStart = null;
    this.onRoundEnd = null;
    this.onMatchEnd = null;
  }

  setState(state) {
    if (this.state === state) return;
    this.state = state;
    this.onStateChange?.(state, this.roundNumber);
  }

  startMatch() {
    this.roundTarget = Number(this.settings.get('roundTarget'));
    this.teamManager.resetMatch();
    this.roundNumber = 0;
    this.setState(RoundState.WAITING_FOR_PLAYERS);
    this.startRound();
  }

  startRound() {
    this.roundNumber += 1;
    this.teamManager.resetRoundState();
    this.bomb.resetRound();
    this.roundTime = 95;
    this.setState(RoundState.PREPARING);
    this.timer = this.prepTime;
    this.onRoundStart?.(this.roundNumber, this.state);
    this.audio.roundStart();
  }

  activateRound() {
    this.setState(RoundState.ACTIVE);
    this.timer = this.roundTime;
    this.onRoundStart?.(this.roundNumber, this.state);
  }

  update(dt) {
    switch (this.state) {
      case RoundState.PREPARING:
        this.timer -= dt;
        if (this.timer <= 0) this.activateRound();
        break;
      case RoundState.ACTIVE:
      case RoundState.BOMB_PLANTED:
        this.timer -= dt;
        this.checkElimination();
        if (this.state === RoundState.ACTIVE && this.timer <= 0) {
          this.endRound('defenders', 'Tempo esgotado');
        }
        break;
      case RoundState.ENDING:
        this.timer -= dt;
        if (this.timer <= 0) {
          const matchWinner = this.matchWinner();
          if (matchWinner) this.finishMatch(matchWinner);
          else this.startRound();
        }
        break;
      default:
        break;
    }
  }

  checkElimination() {
    const alive = this.teamManager.playersAliveCount();
    if (alive.attackers === 0 && this.bomb.state !== BombState.PLANTED) {
      this.endRound('defenders', 'Atacantes eliminados');
      return;
    }
    if (alive.defenders === 0) {
      this.endRound('attackers', 'Defensores eliminados');
    }
  }

  onBombExploded() {
    if (this.state !== RoundState.BOMB_PLANTED) return;
    this.endRound('attackers', 'Bomba explodiu');
  }

  onBombDefused() {
    if (this.state !== RoundState.BOMB_PLANTED && this.state !== RoundState.ACTIVE) return;
    this.endRound('defenders', 'Bomba desarmada');
  }

  endRound(winnerTeam, reason) {
    if (this.state === RoundState.ENDING || this.state === RoundState.MATCH_FINISHED) return;
    this.teamManager.addScore(winnerTeam, 1);
    this.setState(RoundState.ENDING);
    this.timer = this.endDelay;
    this.onRoundEnd?.(winnerTeam, reason, this.roundNumber);
  }

  matchWinner() {
    const target = Number(this.settings.get('roundTarget'));
    if (this.teamManager.attackersScore >= target) return 'attackers';
    if (this.teamManager.defendersScore >= target) return 'defenders';
    return null;
  }

  finishMatch(winnerTeam) {
    this.setState(RoundState.MATCH_FINISHED);
    this.onMatchEnd?.(winnerTeam);
  }

  status() {
    return {
      state: this.state,
      roundNumber: this.roundNumber,
      timer: this.timer,
      roundTarget: Number(this.settings.get('roundTarget')),
      stateLabel: this.stateLabel(),
    };
  }

  stateLabel() {
    switch (this.state) {
      case RoundState.WAITING_FOR_PLAYERS: return 'PREPARANDO';
      case RoundState.PREPARING: return 'PREPARAÇÃO';
      case RoundState.STARTING: return 'INICIANDO';
      case RoundState.ACTIVE: return 'ROUND ATIVO';
      case RoundState.BOMB_PLANTED: return 'BOMBA PLANTADA';
      case RoundState.ENDING: return 'FIM DE ROUND';
      case RoundState.MATCH_FINISHED: return 'PARTIDA ENCERRADA';
      default: return 'AGUARDANDO';
    }
  }
}

