    this.promptText = null;
  }

  show() {
    this.root.classList.remove('hidden');
  }

  hide() {
    this.root.classList.add('hidden');
  }

  update(game, dt) {
    const player = game.player;
    const round = game.round;
    const bomb = game.bomb;
    const teamManager = game.teamManager;

    // Score and alive counts.
    this.elements.atkScore.textContent = teamManager.attackersScore;
    this.elements.defScore.textContent = teamManager.defendersScore;
    const alive = teamManager.playersAliveCount();
    this.elements.atkAlive.textContent = `${alive.attackers} VIVOS`;
    this.elements.defAlive.textContent = `${alive.defenders} VIVOS`;
    this.elements.roundLabel.textContent = `ROUND ${round.roundNumber}`;
    if (round.state === 'bombPlanted' || bomb.state === 'planted' || bomb.state === 'defusing') {
      this.elements.timer.textContent = this.formatTime(bomb.timer);
      this.elements.bombClock.classList.remove('hidden');
      this.elements.bombClock.querySelector('strong').textContent = this.formatTime(bomb.timer);
    } else {
      this.elements.timer.textContent = this.formatTime(round.timer);
      this.elements.bombClock.classList.add('hidden');
    }

    // Health.
    const health = Math.max(0, Math.round(player.health.currentHealth));
    const maxHealth = player.health.maxHealth;
    this.elements.healthFill.style.width = `${(health / maxHealth) * 100}%`;
    this.elements.healthText.textContent = health;
    this.elements.healthFill.parentElement.classList.toggle('low', health <= 35);
    if (player.health.shield > 0) {
      this.elements.shieldRow.classList.remove('hidden');
      this.elements.shieldFill.style.width = `${Math.min(100, player.health.shield)}%`;
    } else this.elements.shieldRow.classList.add('hidden');

    // Weapon.
    const weapon = player.weapon.weapon;
    this.elements.weapon.textContent = weapon.name;
    this.elements.ammo.textContent = weapon.currentAmmo;
    this.elements.reserve.textContent = weapon.reserveAmmo;
    if (player.weapon.reloading) {
      this.elements.reloadBar.classList.remove('hidden');
      const progress = 1 - player.weapon.reloadTimer / weapon.reloadTime;
      this.elements.reloadBar.querySelector('i').style.width = `${progress * 100}%`;
    } else this.elements.reloadBar.classList.add('hidden');

    // Abilities.
    const abilityStatus = player.abilityController.status();
    this.elements.abilityActiveIcon.textContent = abilityStatus.active?.icon || '◈';
    this.elements.abilityActiveName.textContent = abilityStatus.active?.name || 'HABILIDADE';
    if (abilityStatus.activeReady) {
      this.elements.abilityActiveCd.textContent = 'PRONTO';
      this.elements.abilityActiveCd.classList.add('ready');
      this.elements.abilityActiveRing.style.strokeDashoffset = '276';
      this.elements.abilityActive.classList.remove('cooling');
    } else {
      const percent = 1 - abilityStatus.activeCooldown / abilityStatus.active.cooldown;
      this.elements.abilityActiveCd.textContent = `${abilityStatus.activeCooldown.toFixed(1)}s`;
      this.elements.abilityActiveCd.classList.remove('ready');
      this.elements.abilityActiveRing.style.strokeDashoffset = `${276 * (1 - percent)}`;
      this.elements.abilityActive.classList.add('cooling');
    }
    this.elements.abilitySpecialIcon.textContent = abilityStatus.special?.icon || '✦';
    this.elements.abilitySpecialName.textContent = abilityStatus.special?.name || 'ESPECIAL';
    if (abilityStatus.specialReady) {
      this.elements.abilitySpecialCd.textContent = 'PRONTO';
      this.elements.abilitySpecialCd.classList.add('ready');
      this.elements.abilitySpecialRing.style.strokeDashoffset = '276';
      this.elements.abilitySpecial.classList.remove('cooling');
    } else {
      const percent = 1 - abilityStatus.specialCooldown / abilityStatus.special.cooldown;
      this.elements.abilitySpecialCd.textContent = `${abilityStatus.specialCooldown.toFixed(1)}s`;
      this.elements.abilitySpecialCd.classList.remove('ready');
      this.elements.abilitySpecialRing.style.strokeDashoffset = `${276 * (1 - percent)}`;
      this.elements.abilitySpecial.classList.add('cooling');
    }

    // Objective text.
    let objectiveText = 'AVANCE PARA O SITE';
    if (player.team === 'attackers') {
      if (bomb.state === 'notPlanted' || bomb.state === 'planting') objectiveText = 'PLANTE A BOMBA';
      else if (bomb.state === 'planted' || bomb.state === 'defusing') objectiveText = 'DEFENDA A BOMBA';
    } else if (player.team === 'defenders') {
      if (bomb.state === 'notPlanted') objectiveText = 'DEFENDA OS SITES';
      else objectiveText = 'DESARME A BOMBA';
    }
    if (round.state === 'preparingRound') objectiveText = 'PREPARE-SE';
    if (round.state === 'roundEnding') objectiveText = round.lastReason || 'FIM DE ROUND';
    if (this.elements.objectiveText.textContent !== objectiveText) this.elements.objectiveText.textContent = objectiveText;

    // Minimap.
    this.updateMinimap(game);

    // Timers for overlays.
    if (this.hitmarkerTimer > 0) {
      this.hitmarkerTimer -= dt;
      if (this.hitmarkerTimer <= 0) this.elements.hitmarker.classList.remove('show', 'kill');
    }
    if (this.killBannerTimer > 0) {
      this.killBannerTimer -= dt;
      if (this.killBannerTimer <= 0) this.elements.killBanner.classList.add('hidden');
    }
    if (this.damageTimer > 0) {
      this.damageTimer -= dt;
      this.elements.damageVignette.style.opacity = Math.max(0, this.damageTimer / 0.6);
    } else this.elements.damageVignette.style.opacity = 0;

    // Death overlay.
    const dead = !player.health.isAlive;
    this.elements.deathOverlay.classList.toggle('hidden', !dead);
    if (dead) {
      this.elements.deathDamage.textContent = Math.round(player.health.damageTaken);
      this.elements.deathKills.textContent = player.kills || 0;
    }
  }

  formatTime(seconds) {
    const clamped = Math.max(0, seconds);
    const minutes = Math.floor(clamped / 60);
    const remaining = Math.floor(clamped % 60);
    return `${String(minutes).padStart(2, '0')}:${String(remaining).padStart(2, '0')}`;
  }

  hitmarker(isKill = false) {
    this.elements.hitmarker.classList.add('show');
    this.elements.hitmarker.classList.toggle('kill', isKill);
    this.hitmarkerTimer = isKill ? 0.3 : 0.16;
  }

  killBanner(name) {
    this.elements.killName.textContent = name;
    this.elements.killBanner.classList.remove('hidden');
    this.killBannerTimer = 1.6;
  }

  damageFlash() {
    this.damageTimer = 0.55;
  }

  addKillEntry(killerName, victimName, weaponName = 'VECTOR-7') {
    const entry = document.createElement('div');
    entry.className = 'kill-entry';
    entry.innerHTML = `<b>${killerName}</b> <span class="friendly">✕</span> <span class="enemy">${victimName}</span>`;
    this.elements.killfeed.prepend(entry);
    while (this.elements.killfeed.children.length > 5) this.elements.killfeed.lastChild.remove();
    setTimeout(() => entry.remove(), 5000);
  }

  abilityFeed(text) {
    const span = document.createElement('span');
    span.textContent = text;
    this.elements.abilityFeed.innerHTML = '';
    this.elements.abilityFeed.appendChild(span);
    setTimeout(() => span.remove(), 1600);
  }

  toast(message) {
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    this.elements.toastRoot.appendChild(toast);
    setTimeout(() => toast.remove(), 3000);
  }

  showPrompt({ key = 'E', title, sub = '', progress = null }) {
    this.elements.prompt.classList.remove('hidden');
    this.elements.promptKey.textContent = key;
    this.elements.promptTitle.textContent = title;
    this.elements.promptSub.textContent = sub;
    if (progress === null) this.elements.promptFill.style.width = '0%';
    else this.elements.promptFill.style.width = `${Math.max(0, Math.min(100, progress * 100))}%`;
  }

  hidePrompt() {
    this.elements.prompt.classList.add('hidden');
  }

  showRoundBanner(kicker, title, sub) {
    this.elements.roundBannerKicker.textContent = kicker;
    this.elements.roundBannerTitle.textContent = title;
    this.elements.roundBannerSub.textContent = sub;
    this.elements.roundBanner.classList.remove('hidden');
    clearTimeout(this.bannerTimeout);
    this.bannerTimeout = setTimeout(() => this.elements.roundBanner.classList.add('hidden'), 2400);
  }

  hideRoundBanner() {
    this.elements.roundBanner.classList.add('hidden');
  }

  showMatchEnd(winnerTeam, playerTeam, scores, stats) {
    const isWin = winnerTeam === playerTeam;
    this.elements.matchEndTitle.textContent = isWin ? 'VITÓRIA' : 'DERROTA';
    this.elements.matchEndTitle.classList.toggle('loss', !isWin);
    this.elements.matchEndSub.textContent = isWin
      ? 'Sua equipe dominou a Doca Meridiana.'
      : 'Sua equipe foi superada. Ajuste o plano e volte.';
    this.elements.matchScoreAtk.textContent = scores.attackers;
    this.elements.matchScoreDef.textContent = scores.defenders;
    this.elements.matchStats.innerHTML = `
      <div><span>ELIMINAÇÕES</span><b>${stats.kills}</b></div>
      <div><span>DANO CAUSADO</span><b>${Math.round(stats.damage)}</b></div>
      <div><span>ROUNDS</span><b>${stats.rounds}</b></div>
    `;
    this.elements.matchEnd.classList.remove('hidden');
  }

  hideMatchEnd() {
    this.elements.matchEnd.classList.add('hidden');
  }

  updateMinimap(game) {
    const ctx = this.minimapCtx;
    const width = this.elements.minimap.width;
    const height = this.elements.minimap.height;
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = 'rgba(9,13,19,0.65)';
    ctx.fillRect(0, 0, width, height);
    const map = game.map;
    const scaleX = width / 70;
    const scaleZ = height / 44;
    const toX = x => (x + 35) * scaleX;
    const toY = z => (z + 22) * scaleZ;
    // Sites.
    map.siteZones.forEach(zone => {
      ctx.strokeStyle = zone.id === 'A' ? '#ff5b2e' : '#42d9ee';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(toX(zone.center.x), toY(zone.center.y), zone.radius * scaleX, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = zone.id === 'A' ? '#ff5b2e' : '#42d9ee';
      ctx.font = '700 10px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(zone.id, toX(zone.center.x), toY(zone.center.y) + 4);
    });
    // Obstacles.
    ctx.fillStyle = 'rgba(255,255,255,0.08)';
    map.colliders.forEach(collider => {
      ctx.fillRect(toX(collider.minX), toY(collider.minZ), (collider.maxX - collider.minX) * scaleX, (collider.maxZ - collider.minZ) * scaleZ);
    });
    // Entities.
    const drawEntity = (entity, color, isPlayer) => {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(toX(entity.mesh.position.x), toY(entity.mesh.position.z), isPlayer ? 4 : 3, 0, Math.PI * 2);
      ctx.fill();
    };
    game.teamManager.get('attackers').forEach(entity => {
      if (entity.isAlive()) drawEntity(entity, '#ff6b35', entity.isPlayer);
    });
    game.teamManager.get('defenders').forEach(entity => {
      if (entity.isAlive()) drawEntity(entity, '#42d9ee', entity.isPlayer);
    });
    if (game.bomb.visible) {
      ctx.fillStyle = '#ff344b';
      ctx.fillRect(toX(game.bomb.position.x) - 3, toY(game.bomb.position.z) - 3, 6, 6);
    }
    this.elements.minimapSite.textContent = game.bomb.site ? `SITE ${game.bomb.site}` : 'SITES A / B';
  }
}

export class MobileInputController {
  constructor({ settings, audio }) {
    this.settings = settings;
    this.audio = audio;
    this.state = {
      moveX: 0,
      moveZ: 0,
      lookX: 0,
      lookY: 0,
      jump: false,
      sprint: false,
      shoot: false,
      reload: false,
      ability: false,
      special: false,
      interact: false,
      deployHeld: false,
    };
    this.joystickActive = false;
    this.lookActive = false;
    this.lastLook = { x: 0, y: 0 };
    this.elements = {
      joystickZone: document.getElementById('joystick-zone'),
      joystickBase: document.getElementById('joystick-base'),
      joystickKnob: document.getElementById('joystick-knob'),
      lookZone: document.getElementById('look-zone'),
      shoot: document.getElementById('m-btn-shoot'),
      reload: document.getElementById('m-btn-reload'),
      jump: document.getElementById('m-btn-jump'),
      interact: document.getElementById('m-btn-interact'),
      ability: document.getElementById('m-btn-ability'),
      special: document.getElementById('m-btn-special'),
      pause: document.getElementById('pause-btn'),
    };
    this.init();
  }

  init() {
    const isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    document.body.classList.toggle('touch-device', isTouch);
    if (isTouch) this.elements.mobileControls = document.getElementById('mobile-controls');

    const zone = this.elements.joystickZone;
    const knob = this.elements.joystickKnob;
    const base = this.elements.joystickBase;
    const handleJoystick = event => {
      event.preventDefault();
      const rect = zone.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;
      const clientX = event.touches ? event.touches[0].clientX : event.clientX;
      const clientY = event.touches ? event.touches[0].clientY : event.clientY;
      const maxRadius = rect.width / 2 - 12;
      let dx = clientX - centerX;
      let dy = clientY - centerY;
      const distance = Math.hypot(dx, dy);
      if (distance > maxRadius) {
        dx = (dx / distance) * maxRadius;
        dy = (dy / distance) * maxRadius;
      }
      knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
      const normalizedX = dx / maxRadius;
      const normalizedY = dy / maxRadius;
      this.state.moveX = normalizedX;
      this.state.moveZ = normalizedY;
      this.state.sprint = Math.hypot(normalizedX, normalizedY) > 0.82;
      this.joystickActive = true;
    };
    const resetJoystick = () => {
      this.joystickActive = false;
      this.state.moveX = 0;
      this.state.moveZ = 0;
      this.state.sprint = false;
      knob.style.transform = 'translate(-50%,-50%)';
    };
    zone.addEventListener('pointerdown', event => {
      zone.setPointerCapture(event.pointerId);
      handleJoystick(event);
      this.vibrate(8);
    });
    zone.addEventListener('pointermove', event => { if (this.joystickActive) handleJoystick(event); });
    zone.addEventListener('pointerup', resetJoystick);
    zone.addEventListener('pointercancel', resetJoystick);
    zone.addEventListener('lostpointercapture', resetJoystick);

    const lookZone = this.elements.lookZone;
    lookZone.addEventListener('pointerdown', event => {
      lookZone.setPointerCapture(event.pointerId);
      this.lookActive = true;
      this.lastLook.x = event.clientX;
      this.lastLook.y = event.clientY;
    });
    lookZone.addEventListener('pointermove', event => {
      if (!this.lookActive) return;
      const sensitivity = this.settings.get('sensitivity');
      const invert = this.settings.get('invertY') ? -1 : 1;
      const dx = event.clientX - this.lastLook.x;
      const dy = event.clientY - this.lastLook.y;
      this.state.lookX += dx * 0.0024 * sensitivity;
      this.state.lookY += dy * 0.0024 * sensitivity * invert;
      this.lastLook.x = event.clientX;
      this.lastLook.y = event.clientY;
    });
    const resetLook = () => {
      this.lookActive = false;
    };
    lookZone.addEventListener('pointerup', resetLook);
    lookZone.addEventListener('pointercancel', resetLook);
    lookZone.addEventListener('lostpointercapture', resetLook);

    this.bindButton(this.elements.shoot, 'shoot', true);
    this.bindButton(this.elements.reload, 'reload', true);
    this.bindButton(this.elements.jump, 'jump', true);
    this.bindButton(this.elements.interact, 'interact', true);
    this.bindButton(this.elements.ability, 'ability', true);
    this.bindButton(this.elements.special, 'special', true);
    this.elements.pause?.addEventListener('click', () => this.audio.ui('click'));
  }

  bindButton(element, key, hold) {
    if (!element) return;
    const down = event => {
      event.preventDefault();
      this.state[key] = true;
      element.classList.add('active');
      this.vibrate(4);
      if (key === 'ability' || key === 'special') this.audio.ui('click');
    };
    const up = event => {
      event.preventDefault();
      this.state[key] = false;
      element.classList.remove('active');
    };
    element.addEventListener('pointerdown', down);
    element.addEventListener('pointerup', up);
    element.addEventListener('pointercancel', up);
    element.addEventListener('pointerleave', up);
  }

  vibrate(pattern = 4) {
    if (!this.settings.get('vibration') || !navigator.vibrate) return;
    try { navigator.vibrate(pattern); } catch (error) { /* ignore */ }
  }

  update() {
    // Reset per-frame deltas; they are consumed by the camera controller.
    this.frameLookX = this.state.lookX;
    this.frameLookY = this.state.lookY;
    this.state.lookX = 0;
    this.state.lookY = 0;
  }

  read() {
    return {
      moveX: this.state.moveX,
      moveZ: this.state.moveZ,
      lookX: this.frameLookX || 0,
      lookY: this.frameLookY || 0,
      jump: this.state.jump,
      sprint: this.state.sprint,
      shoot: this.state.shoot,
      reload: this.state.reload,
      ability: this.state.ability,
      special: this.state.special,
      interact: this.state.interact,
    };
  }

  showInteract(label = 'INTERAGIR') {
    if (!this.elements.interact) return;
    this.elements.interact.classList.remove('hidden');
    this.elements.interact.querySelector('small').textContent = label;
  }

  hideInteract() {
    this.elements.interact?.classList.add('hidden');
  }

  consumeLook() {
    const result = { lookX: this.frameLookX || 0, lookY: this.frameLookY || 0 };
    this.frameLookX = 0;
    this.frameLookY = 0;
    return result;
  }
}

export class MobileInteractionController {
  constructor({ hud, mobileInput }) {
    this.hud = hud;
    this.mobileInput = mobileInput;
  }

  update({ player, bomb, round }) {
    if (!player.isAlive()) {
      this.hud.hidePrompt();
      this.mobileInput.hideInteract();
      return;
    }
    const isAttacker = player.team === 'attackers';
    if (round.state === 'preparingRound') {
      this.hud.hidePrompt();
      this.mobileInput.hideInteract();
      return;
    }
    if (isAttacker && bomb.canPlant(player)) {
      const label = bomb.state === 'planting' ? 'PLANTANDO' : 'PLANTAR';
      this.hud.showPrompt({
        key: 'E',
        title: 'PLANTAR BOMBA',
        sub: 'Mantenha pressionado até concluir',
        progress: bomb.state === 'planting' ? bomb.plantProgress / 3.2 : 0,
      });
      this.mobileInput.showInteract(label);
      return;
    }
    if (!isAttacker && bomb.canDefuse(player)) {
      const label = bomb.state === 'defusing' ? 'DESARMANDO' : 'DESARMAR';
      this.hud.showPrompt({
        key: 'E',
        title: 'DESARMAR BOMBA',
        sub: 'Mantenha pressionado até concluir',
        progress: bomb.state === 'defusing' ? bomb.defuseProgress / 5 : 0,
      });
      this.mobileInput.showInteract(label);
      return;
    }
    this.hud.hidePrompt();
    this.mobileInput.hideInteract();
  }
}

import { characters, getCharacter, roleInfo, characterInitials } from '../data/characters.js';
import { weapons, weaponStatsForUI } from '../data/weapons.js';

export class MenuController {
  constructor({ settings, audio, onCharacterChanged, onSkinChanged, onStartMatch }) {
    this.settings = settings;
    this.audio = audio;
    this.onCharacterChanged = onCharacterChanged;
    this.onSkinChanged = onSkinChanged;
    this.onStartMatch = onStartMatch;
    this.selectedSide = 'attackers';
    this.screens = document.querySelectorAll('[data-screen-view]');
    this.selectedCharacter = getCharacter(settings.get('selectedCharacter'));
    this.initMenu();
    this.buildRoster();
    this.buildArmory();
    this.buildCustomization();
    this.bindSettings();
    this.updateHero();
    this.updateDetail();
    this.updateDeploy();
  }

  initMenu() {
    document.querySelectorAll('[data-screen]').forEach(button => {
      button.addEventListener('click', event => {
        event.preventDefault();
        const target = button.dataset.screen;
        if (target === 'characters' && button.id === 'deploy-change') {
          this.hideDeploy();
        }
        this.showScreen(target);
        this.audio.ui(target === 'main' ? 'back' : 'click');
      });
    });
    document.getElementById('quickplay-btn').addEventListener('click', () => {
      this.audio.ui('confirm');
      this.showDeploy();
    });
    document.getElementById('deploy-close').addEventListener('click', () => {
      this.audio.ui('back');
      this.hideDeploy();
    });
    document.querySelectorAll('.side-card').forEach(card => {
      card.addEventListener('click', () => {
        document.querySelectorAll('.side-card').forEach(other => other.classList.remove('selected'));
        card.classList.add('selected');
        this.selectedSide = card.dataset.side;
        this.audio.ui('click');
      });
    });
    document.getElementById('start-match-btn').addEventListener('click', () => {
      const difficulty = document.getElementById('bot-difficulty').value;
      const roundTarget = Number(document.getElementById('round-target').value);
      this.settings.set('botDifficulty', difficulty);
      this.settings.set('roundTarget', roundTarget);
      this.audio.ui('deploy');
      this.hideDeploy();
      this.onStartMatch?.({ side: this.selectedSide, difficulty, roundTarget });
    });
    document.getElementById('audio-toggle').addEventListener('click', () => {
      const master = this.settings.get('masterVolume');
      const muted = master > 0;
      this.settings.set('masterVolume', muted ? 0 : 0.8);
      document.getElementById('audio-toggle').classList.toggle('active', !muted);
      this.audio.ui('click');
    });
    document.getElementById('fullscreen-btn').addEventListener('click', () => {
      if (!document.fullscreenElement) document.documentElement.requestFullscreen?.().catch(() => {});
      else document.exitFullscreen?.();
      this.audio.ui('click');
    });
  }

  showScreen(name) {
    this.screens.forEach(screen => screen.classList.toggle('active', screen.dataset.screenView === name));
    this.currentScreen = name;
    if (name === 'main') this.updateHero();
  }

  currentScreenName() {
    return this.currentScreen || 'main';
  }

  showDeploy() {
    document.getElementById('deploy-modal').classList.remove('hidden');
    this.updateDeploy();
  }

  hideDeploy() {
    document.getElementById('deploy-modal').classList.add('hidden');
  }

  updateHero() {
    const character = this.selectedCharacter;
    document.getElementById('hero-name').textContent = character.name;
    const role = roleInfo(character.role);
    document.getElementById('hero-role').textContent = `${role.label} • ${character.codename || role.description.split(' ')[0]}`;
    document.getElementById('hero-desc').textContent = character.description;
    document.getElementById('hero-age').textContent = `${character.age} ANOS`;
  }

  buildRoster() {
    const roster = document.getElementById('roster');
    roster.innerHTML = '';
    characters.forEach((character, index) => {
      const role = roleInfo(character.role);
      const card = document.createElement('button');
      card.className = 'roster-card';
      card.dataset.characterId = character.id;
      card.style.setProperty('--accent', role.color);
      card.innerHTML = `
        <span class="roster-num">${String(index + 1).padStart(2, '0')}</span>
        <span class="roster-avatar">${characterInitials(character)}</span>
        <span class="roster-name">${character.name}</span>
        <span class="roster-role">${role.label}</span>
      `;
      card.addEventListener('click', () => {
        this.selectCharacter(character.id);
        this.audio.ui('click');
      });
      roster.appendChild(card);
    });
    this.updateRosterSelection();
  }

  updateRosterSelection() {
    document.querySelectorAll('.roster-card').forEach(card => {
      card.classList.toggle('selected', card.dataset.characterId === this.selectedCharacter.id);
    });
  }

  selectCharacter(id) {
    const character = getCharacter(id);
    this.selectedCharacter = character;
    this.settings.set('selectedCharacter', id);
    this.settings.set('selectedSkin', 0);
    this.updateRosterSelection();
    this.updateDetail();
    this.updateHero();
    this.updateCustomization();
    this.updateDeploy();
    this.onCharacterChanged?.(character, 0);
  }

  updateDetail() {
    const character = this.selectedCharacter;
    const index = characters.findIndex(c => c.id === character.id);
    const role = roleInfo(character.role);
    document.getElementById('detail-index').textContent = `${String(index + 1).padStart(2, '0')} / ${String(characters.length).padStart(2, '0')}`;
    document.getElementById('detail-name').textContent = character.name;
    document.getElementById('detail-age').textContent = `${character.age} ANOS • ${character.codename || role.label}`;
    document.getElementById('detail-role').textContent = role.label;
    document.getElementById('detail-role').style.setProperty('--accent', role.color);
    document.querySelector('.character-detail').style.setProperty('--accent', role.color);
    document.getElementById('detail-desc').textContent = `${character.description} ${character.appearance} Personalidade: ${character.personality}`;
    const healthPercent = Math.min(100, (character.health / 120) * 100);
    const speedPercent = Math.min(100, (character.movement.run / 8.2) * 100);
    const controlPercent = Math.max(25, Math.min(100, 100 - character.movement.mass * 55));
    document.getElementById('stat-health').style.width = `${healthPercent}%`;
    document.getElementById('stat-health-val').textContent = character.health;
    document.getElementById('stat-speed').style.width = `${speedPercent}%`;
    document.getElementById('stat-speed-val').textContent = character.movement.run.toFixed(1);
    document.getElementById('stat-control').style.width = `${controlPercent}%`;
    document.getElementById('stat-control-val').textContent = Math.round(controlPercent);
    const abilities = [
      { label: 'PASSIVA', icon: '◆', ...character.passive },
      { label: 'ATIVA', icon: character.active.icon, ...character.active },
      { label: 'ESPECIAL', icon: character.special.icon, ...character.special },
    ];
    document.getElementById('detail-abilities').innerHTML = abilities.map(ability => `
      <div class="ability-row">
        <div class="ab-icon">${ability.icon || '◆'}</div>
        <div><b>${ability.name}</b><small>${ability.description}</small></div>
        <div class="ab-type">${ability.label}<br>${ability.cooldown ? `${ability.cooldown}s` : 'AUTO'}</div>
      </div>
    `).join('');
    const swatches = document.getElementById('detail-skins');
    swatches.innerHTML = '';
    character.skins.forEach((skin, index) => {
      const swatch = document.createElement('button');
      swatch.className = 'swatch' + (index === (this.settings.get('selectedSkin') || 0) ? ' active' : '');
      swatch.style.background = `linear-gradient(120deg, ${skin.colors.cloth}, ${skin.colors.accent})`;
      swatch.title = skin.name;
      swatch.addEventListener('click', () => {
        this.settings.set('selectedSkin', index);
        this.updateDetail();
        this.updateCustomization();
        this.onSkinChanged?.(character, index);
        this.audio.ui('click');
      });
      swatches.appendChild(swatch);
    });
    document.getElementById('select-character-btn').addEventListener('click', () => {
      this.audio.ui('confirm');
      this.showScreen('main');
      this.updateHero();
    });
    document.getElementById('detail-deploy-btn').addEventListener('click', () => {
      this.audio.ui('confirm');
      this.showDeploy();
    });
  }

  buildArmory() {
    const grid = document.getElementById('armory-grid');
    grid.innerHTML = '';
    Object.values(weapons).forEach(weapon => {
      const stats = weaponStatsForUI(weapon.id);
      const card = document.createElement('div');
      card.className = 'weapon-card';
      card.style.setProperty('--accent', weapon.id === 'pistol' ? '#42d9ee' : weapon.id === 'sniper' ? '#f8c95c' : weapon.id === 'shotgun' ? '#ff5b2e' : '#74e69a');
      card.innerHTML = `
        <div class="weapon-art"><div class="gun-silhouette"></div></div>
        <h3>${weapon.name}</h3>
        <span class="weapon-type">${weapon.type}</span>
        <div class="weapon-stats">
          <div class="weapon-stat"><span>DANO</span><div class="bar"><i style="width:${Math.min(100, weapon.damage / 80 * 100)}%"></i></div><b>${weapon.damage}</b></div>
          <div class="weapon-stat"><span>CADÊNCIA</span><div class="bar"><i style="width:${Math.min(100, stats.fireRate / 900 * 100)}%"></i></div><b>${stats.fireRate}</b></div>
          <div class="weapon-stat"><span>MUNIÇÃO</span><div class="bar"><i style="width:${Math.min(100, weapon.magazineSize / 30 * 100)}%"></i></div><b>${weapon.magazineSize}</b></div>
          <div class="weapon-stat"><span>PRECISÃO</span><div class="bar"><i style="width:${stats.accuracy}%"></i></div><b>${stats.accuracy}%</b></div>
        </div>
        <div class="weapon-footer"><span>${weapon.automatic ? 'AUTOMÁTICA' : 'SEMI-AUTOMÁTICA'}</span><b>DISPONÍVEL</b></div>
      `;
      grid.appendChild(card);
    });
  }

  buildCustomization() {
    const banners = [
      { id: 0, name: 'VC', colors: ['#ff5b2e', '#7b2b1c'] },
      { id: 1, name: 'ARENA', colors: ['#42d9ee', '#143241'] },
      { id: 2, name: 'MERIDIANA', colors: ['#f8c95c', '#40301c'] },
    ];
    const grid = document.getElementById('banner-grid');
    grid.innerHTML = '';
    banners.forEach(banner => {
      const button = document.createElement('button');
      button.className = 'banner-thumb';
      button.style.setProperty('--b1', banner.colors[0]);
      button.style.setProperty('--b2', banner.colors[1]);
      button.textContent = banner.name;
      button.addEventListener('click', () => {
        this.settings.set('selectedBanner', banner.id);
        this.updateCustomization();
        this.audio.ui('click');
      });
      grid.appendChild(button);
    });
    this.updateCustomization();
  }

  updateCustomization() {
    const character = this.selectedCharacter;
    const role = roleInfo(character.role);
    document.getElementById('custom-name').textContent = character.name;
    document.getElementById('custom-role').textContent = `${role.label} • ${character.codename || role.description.split('.')[0]}`;
    const swatches = document.getElementById('custom-swatches');
    swatches.innerHTML = '';
    character.skins.forEach((skin, index) => {
      const swatch = document.createElement('button');
      swatch.className = 'custom-swatch' + (index === (this.settings.get('selectedSkin') || 0) ? ' active' : '');
      swatch.style.background = `linear-gradient(120deg, ${skin.colors.cloth}, ${skin.colors.gear})`;
      swatch.innerHTML = `<span>${skin.name}</span>`;
      swatch.addEventListener('click', () => {
        this.settings.set('selectedSkin', index);
        this.updateDetail();
        this.updateCustomization();
        this.onSkinChanged?.(character, index);
        this.audio.ui('click');
      });
      swatches.appendChild(swatch);
    });
    document.querySelectorAll('.banner-thumb').forEach((thumb, index) => {
      thumb.classList.toggle('active', index === (this.settings.get('selectedBanner') || 0));
    });
  }

  updateDeploy() {
    const character = this.selectedCharacter;
    document.getElementById('deploy-avatar').textContent = characterInitials(character);
    document.getElementById('deploy-name').textContent = character.name;
    document.getElementById('deploy-role').textContent = `${roleInfo(character.role).label} • ${character.codename || 'OPERADORA'}`;
    document.getElementById('bot-difficulty').value = this.settings.get('botDifficulty');
    document.getElementById('round-target').value = this.settings.get('roundTarget');
    document.querySelectorAll('.side-card').forEach(card => {
      card.classList.toggle('selected', card.dataset.side === this.selectedSide);
    });
  }

  bindSettings() {
    const settings = this.settings;
    const bindRange = (id, key, transform = value => value, output = value => value) => {
      const element = document.getElementById(id);
      const outputElement = element.nextElementSibling;
      const update = () => {
        const raw = Number(element.value);
        const value = transform(raw);
        if (outputElement) outputElement.textContent = output(value);
        const percent = (raw - Number(element.min)) / (Number(element.max) - Number(element.min)) * 100;
        element.style.setProperty('--p', `${percent}%`);
        settings.set(key, value);
      };
      element.addEventListener('input', update);
      element.value = settings.get(key);
      update();
      return element;
    };

    const bindToggle = (id, key) => {
      const element = document.getElementById(id);
      element.checked = !!settings.get(key);
      element.addEventListener('change', () => settings.set(key, element.checked));
      return element;
    };

    const bindSelect = (id, key) => {
      const element = document.getElementById(id);
      element.value = settings.get(key);
      element.addEventListener('change', () => settings.set(key, element.value));
      return element;
    };

    bindRange('sens-range', 'sensitivity', value => value, value => `${value.toFixed(1)}×`);
    bindRange('stick-range', 'stickScale', value => value / 100, value => `${Math.round(value * 100)}%`);
    bindRange('master-range', 'masterVolume', value => value / 100, value => `${Math.round(value)}%`);
    bindRange('music-range', 'musicVolume', value => value / 100, value => `${Math.round(value)}%`);
    bindRange('sfx-range', 'sfxVolume', value => value / 100, value => `${Math.round(value)}%`);
    bindRange('fov-range', 'fov', value => value, value => `${value}°`);
    bindSelect('quality-select', 'quality');
    bindToggle('vibration-toggle', 'vibration');
    bindToggle('invert-toggle', 'invertY');
    bindToggle('shadows-toggle', 'shadows');
    bindToggle('particles-toggle', 'particles');

    document.getElementById('reset-settings').addEventListener('click', () => {
      this.settings.reset();
      this.audio.ui('back');
      window.location.reload();
    });
  }
}

import * as THREE from 'three';
import { characters, getCharacter, roleInfo, characterInitials } from '../data/characters.js';
import { SettingsManager } from './settingsManager.js';
import { AudioManager } from './audioManager.js';
import { TeamManager } from './teamManager.js';
import { MapBuilder } from '../world/mapBuilder.js';
import { RoundManager, RoundState } from './roundManager.js';
import { BombController, BombState } from '../objectives/bombController.js';
import { HUDController } from '../ui/hudController.js';
import { MenuController } from '../ui/menuController.js';
import { PlayerController } from '../player/playerController.js';
import { BotController } from '../bots/botController.js';
import { AbilityController } from '../abilities/abilityController.js';
import { MobileInputController } from '../input/mobileInputController.js';
import { MobileInteractionController } from '../input/mobileInteractionController.js';
import { createCharacterMesh } from '../three/characterMesh.js';

export class GameManager {
  constructor() {
    this.canvas = document.getElementById('game-canvas');
    this.settings = new SettingsManager();
    this.audio = new AudioManager(this.settings);
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: this.settings.get('quality') !== 'low', powerPreference: 'high-performance' });
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, this.settings.get('quality') === 'high' ? 2 : 1.4));
    this.renderer.shadowMap.enabled = this.settings.get('shadows');
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(this.settings.get('fov'), window.innerWidth / window.innerHeight, 0.1, 220);
    this.clock = new THREE.Clock();
    this.teamManager = new TeamManager();
    this.hud = new HUDController();
    this.menu = new MenuController({
      settings: this.settings,
      audio: this.audio,
      onCharacterChanged: (character, skinIndex) => this.setCharacterPreview(character, skinIndex),
      onSkinChanged: (character, skinIndex) => this.setCharacterPreview(character, skinIndex),
      onStartMatch: config => this.startMatch(config),
    });
    this.mobileInput = new MobileInputController({ settings: this.settings, audio: this.audio });
    this.interaction = new MobileInteractionController({ hud: this.hud, mobileInput: this.mobileInput });
    this.mode = 'menu';
    this.previewMesh = null;
    this.previewGroup = null;
    this.map = null;
    this.entities = [];
    this.player = null;
    this.round = null;
    this.bomb = null;
    this.tracers = [];
    this.impacts = [];
    this.input = { moveX: 0, moveZ: 0, lookX: 0, lookY: 0, jump: false, sprint: false, shoot: false, reload: false, ability: false, special: false, interact: false };
    this.keys = new Set();
    this.mouseDown = false;
    this.previewTargetYaw = 0;
    this.previewYaw = 0;
    this.previewDistance = 3.4;
    this.previewPitch = 0.15;
    this.stats = { kills: 0, damage: 0, rounds: 0 };
    this.pointerLocked = false;
    this.paused = false;
    this.init();
  }

  init() {
    this.setupResize();
    this.setupInput();
    this.setupMenuShowroom();
    this.setupOverlays();
    this.animate();
    setTimeout(() => {
      document.getElementById('loading-screen').classList.add('done');
      this.menu.showScreen('main');
    }, 450);
    window.addEventListener('pointerdown', () => this.audio.resume(), { once: true });
    window.addEventListener('keydown', () => this.audio.resume(), { once: true });
  }

  setupResize() {
    window.addEventListener('resize', () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      this.renderer.setSize(width, height, false);
      this.camera.aspect = width / height;
      this.camera.updateProjectionMatrix();
    });
  }

  setupInput() {
    window.addEventListener('keydown', event => {
      this.keys.add(event.code);
      if (event.code === 'Escape' && this.mode === 'match') this.togglePause(true);
      if (['Space', 'KeyQ', 'KeyF', 'KeyE', 'KeyR', 'Digit1', 'Digit2'].includes(event.code)) event.preventDefault();
    });
    window.addEventListener('keyup', event => this.keys.delete(event.code));
    this.canvas.addEventListener('mousedown', event => {
      if (this.mode !== 'match') return;
      this.mouseDown = true;
      if (!this.pointerLocked && !this.paused && event.button === 0) this.requestPointerLock();
    });
    window.addEventListener('mouseup', () => { this.mouseDown = false; });
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas;
      if (!this.pointerLocked && this.mode === 'match' && !this.paused) this.togglePause(true);
    });
    document.addEventListener('mousemove', event => {
      if (!this.pointerLocked || this.mode !== 'match' || this.paused) return;
      const sensitivity = this.settings.get('sensitivity');
      const invert = this.settings.get('invertY') ? -1 : 1;
      this.player.yaw -= event.movementX * 0.0022 * sensitivity;
      this.player.pitch -= event.movementY * 0.0022 * sensitivity * invert;
      this.player.pitch = THREE.MathUtils.clamp(this.player.pitch, -Math.PI / 2.05, Math.PI / 2.05);
    });
    this.canvas.addEventListener('pointerdown', event => {
      if (this.mode !== 'menu') return;
      this.previewDrag = { x: event.clientX, y: event.clientY, active: true };
      this.canvas.setPointerCapture(event.pointerId);
    });
    this.canvas.addEventListener('pointermove', event => {
      if (this.mode !== 'menu' || !this.previewDrag?.active) return;
      const dx = event.clientX - this.previewDrag.x;
      const dy = event.clientY - this.previewDrag.y;
      this.previewDrag.x = event.clientX;
      this.previewDrag.y = event.clientY;
      this.previewTargetYaw += dx * 0.008;
      this.previewPitch = THREE.MathUtils.clamp(this.previewPitch + dy * 0.004, -0.35, 0.55);
    });
    this.canvas.addEventListener('pointerup', () => { this.previewDrag = null; });
    this.canvas.addEventListener('wheel', event => {
      if (this.mode !== 'menu') return;
      this.previewDistance = THREE.MathUtils.clamp(this.previewDistance + event.deltaY * 0.002, 1.6, 6);
      event.preventDefault();
    }, { passive: false });
  }

  requestPointerLock() {
    if (this.canvas.requestPointerLock) this.canvas.requestPointerLock();
  }

  setupMenuShowroom() {
    this.scene.clear();
    const showroom = new THREE.Group();
    showroom.name = 'showroom';
    const floor = new THREE.Mesh(new THREE.CircleGeometry(4, 42), new THREE.MeshLambertMaterial({ color: 0x111820 }));
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    showroom.add(floor);
    const platform = new THREE.Mesh(new THREE.CylinderGeometry(1.35, 1.5, 0.16, 42), new THREE.MeshLambertMaterial({ color: 0x1e2630 }));
    platform.position.y = 0.08;
    showroom.add(platform);
    const rim = new THREE.Mesh(new THREE.TorusGeometry(1.42, 0.025, 8, 42), new THREE.MeshBasicMaterial({ color: 0xff5b2e }));
    rim.rotation.x = Math.PI / 2;
    rim.position.y = 0.16;
    showroom.add(rim);
    const keyLight = new THREE.DirectionalLight(0xffe4c6, 1.15);
    keyLight.position.set(2.5, 4.5, 3);
    keyLight.castShadow = true;
    showroom.add(keyLight);
    const rimLight = new THREE.PointLight(0x42d9ee, 1.2, 10, 2);
    rimLight.position.set(-2.6, 1.5, -1.8);
    showroom.add(rimLight);
    const backLight = new THREE.PointLight(0xff5b2e, 0.8, 10, 2);
    backLight.position.set(2.6, 1.4, -2.2);
    showroom.add(backLight);
    const ambient = new THREE.AmbientLight(0x596470, 0.65);
    showroom.add(ambient);
    const fog = new THREE.Fog(0x080b12, 5, 16);
    this.scene.fog = fog;
    this.scene.background = new THREE.Color(0x070a10);
    this.scene.add(showroom);
    this.showroom = showroom;
    this.setCharacterPreview(getCharacter(this.settings.get('selectedCharacter')), this.settings.get('selectedSkin'));
  }

  setCharacterPreview(character, skinIndex = 0) {
    if (!this.showroom) return;
    if (this.previewMesh) {
      this.showroom.remove(this.previewMesh.group);
      this.previewMesh.group.traverse(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    }
    this.previewMesh = createCharacterMesh(character, skinIndex);
    this.previewMesh.group.position.set(0, 0.16, 0);
    this.previewMesh.group.scale.setScalar(1.1);
    this.showroom.add(this.previewMesh.group);
    this.selectedCharacter = character;
    this.selectedSkinIndex = skinIndex;
  }

  setupOverlays() {
    document.getElementById('resume-btn').addEventListener('click', () => this.togglePause(false));
    document.getElementById('abandon-btn').addEventListener('click', () => this.returnToMenu());
    document.getElementById('return-menu-btn').addEventListener('click', () => this.returnToMenu());
    document.getElementById('rematch-btn').addEventListener('click', () => {
      this.hideMatchEnd();
      this.startMatch(this.lastMatchConfig);
    });
  }

  togglePause(paused) {
    this.paused = paused;
    document.getElementById('pause-overlay').classList.toggle('hidden', !paused);
    if (paused) document.exitPointerLock?.();
  }

  startMatch({ side = 'attackers', difficulty = 'veteran', roundTarget = 4 }) {
    this.lastMatchConfig = { side, difficulty, roundTarget };
    this.mode = 'match';
    this.paused = false;
    this.stats = { kills: 0, damage: 0, rounds: 0 };
    document.getElementById('menu-layer').classList.add('hidden-menu');
    this.hud.show();
    this.hud.hideMatchEnd();
    this.scene.clear();
    this.scene.fog = new THREE.Fog(0x080b12, 24, 86);
    this.scene.background = new THREE.Color(0x070a10);
    this.map = new MapBuilder(this.scene, this.settings.get('quality'));
    this.attackSite = Math.random() < 0.5 ? 'A' : 'B';
    this.defendSite = this.attackSite === 'A' ? 'B' : 'A';
    this.buildTeams(side, difficulty);
    this.abilityController = new AbilityController(this.scene, this.audio, this.settings);
    this.player.abilityController = this.abilityController;
    this.bomb = new BombController({ scene: this.scene, map: this.map, audio: this.audio });
    this.round = new RoundManager({
      teamManager: this.teamManager,
      bomb: this.bomb,
      audio: this.audio,
      settings: this.settings,
    });
    this.round.onRoundStart = (roundNumber, state) => this.handleRoundStart(roundNumber, state);
    this.round.onRoundEnd = (winnerTeam, reason, roundNumber) => this.handleRoundEnd(winnerTeam, reason, roundNumber);
    this.round.onMatchEnd = winnerTeam => this.handleMatchEnd(winnerTeam);
    this.hud.elements.playerName.textContent = this.player.character.name;
    this.hud.elements.playerRole.textContent = roleInfo(this.player.character.role).label;
    this.round.startMatch();
    this.audio.ambience();
  }

  buildTeams(playerSide, difficulty) {
    this.teamManager.clear();
    this.entities = [];
    const usedCharacters = [...characters].sort(() => Math.random() - 0.5);
    const playerCharacter = getCharacter(this.settings.get('selectedCharacter'));
    this.player = new PlayerController({
      camera: this.camera,
      scene: this.scene,
      settings: this.settings,
      audio: this.audio,
      map: this.map,
      character: playerCharacter,
      team: playerSide,
    });
    this.player.enemiesList = [];
    this.player.alliesList = [];
    this.teamManager.register(this.player, playerSide);
    this.entities.push(this.player);
    const enemySide = playerSide === 'attackers' ? 'defenders' : 'attackers';
    const sameSideBots = [];
    const enemyBots = [];
    for (let i = 0; i < 4; i += 1) {
      const bot = this.createBot(usedCharacters[(i + 1) % usedCharacters.length], playerSide, difficulty, `ally-${i}`);
      sameSideBots.push(bot);
    }
    for (let i = 0; i < 5; i += 1) {
      const bot = this.createBot(usedCharacters[(i + 5) % usedCharacters.length], enemySide, difficulty, `enemy-${i}`);
      enemyBots.push(bot);
    }
    const attackers = playerSide === 'attackers' ? [this.player, ...sameSideBots] : enemyBots;
    const defenders = playerSide === 'defenders' ? [this.player, ...sameSideBots] : enemyBots;
    attackers.forEach((entity, index) => {
      const spawn = this.map.spawnPoints.attackers[index % this.map.spawnPoints.attackers.length];
      entity.setSpawn(spawn, Math.PI);
      this.teamManager.register(entity, 'attackers');
    });
    defenders.forEach((entity, index) => {
      const spawn = this.map.spawnPoints.defenders[index % this.map.spawnPoints.defenders.length];
      entity.setSpawn(spawn, 0);
      this.teamManager.register(entity, 'defenders');
    });
    this.entities = [...attackers, ...defenders];
    this.entities.forEach(entity => {
      entity.enemiesList = entity.team === 'attackers' ? [...defenders] : [...attackers];
      entity.alliesList = entity.team === 'attackers' ? [...attackers] : [...defenders];
    });
    const carrier = attackers.find(entity => entity.isPlayer) || attackers[0];
    carrier.bombRole = 'carrier';
    attackers.forEach(entity => { if (entity !== carrier) entity.bombRole = 'support'; });
    defenders.forEach(entity => { entity.bombRole = 'defender'; });
    this.player.weapon.switchTo('primary');
  }

  createBot(character, team, difficulty, id) {
    return new BotController({ scene: this.scene, map: this.map, audio: this.audio, character, team, difficulty, id, settings: this.settings });
  }

  handleRoundStart(roundNumber, state) {
    this.stats.rounds = roundNumber;
    this.assignSites();
    this.hud.hideRoundBanner();
    if (state === 'preparingRound') {
      this.hud.showRoundBanner(`ROUND ${roundNumber}`, 'PREPARE-SE', 'Restaurando equipamento e habilidades');
    } else {
      this.hud.showRoundBanner(`ROUND ${roundNumber}`, 'ROUND ATIVO', this.attackSite ? `OBJETIVO: SITE ${this.attackSite}` : 'ELIMINE OS ADVERSÁRIOS');
      this.audio.roundStart();
    }
    this.hud.toast(this.player.team === 'attackers' ? 'Você é ATTACKER. Plante a bomba.' : 'Você é DEFENDER. Proteja os sites.');
  }

  assignSites() {
    this.attackSite = Math.random() < 0.5 ? 'A' : 'B';
    this.defendSite = this.attackSite === 'A' ? 'B' : 'A';
    // Spread bots toward objectives.
    this.teamManager.get('attackers').forEach((entity, index) => {
      if (entity.bombRole === 'carrier') entity.patrolIndex = 0;
      else entity.patrolIndex = index;
    });
    this.teamManager.get('defenders').forEach((entity, index) => {
      entity.patrolIndex = index;
    });
  }

  handleRoundEnd(winnerTeam, reason, roundNumber) {
    this.stats.rounds = roundNumber;
    this.hud.showRoundBanner(
      `ROUND ${roundNumber}`,
      winnerTeam === 'attackers' ? 'ATTACKERS VENCERAM' : 'DEFENDERS VENCERAM',
      reason,
    );
    this.audio.victory();
    if (winnerTeam !== this.player.team) this.audio.defeat();
    this.hud.addKillEntry(winnerTeam === 'attackers' ? 'ATTACKERS' : 'DEFENDERS', reason);
    // Reset for next round after delay is handled by RoundManager.
  }

  handleMatchEnd(winnerTeam) {
    const scores = { attackers: this.teamManager.attackersScore, defenders: this.teamManager.defendersScore };
    this.hud.showMatchEnd(winnerTeam, this.player.team, scores, {
      kills: this.stats.kills,
      damage: this.stats.damage,
      rounds: this.round.roundNumber,
    });
    if (winnerTeam === this.player.team) this.audio.victory();
    else this.audio.defeat();
    document.exitPointerLock?.();
  }

  hideMatchEnd() {
    this.hud.hideMatchEnd();
  }

  returnToMenu() {
    this.mode = 'menu';
    this.paused = false;
    document.exitPointerLock?.();
    document.getElementById('menu-layer').classList.remove('hidden-menu');
    this.hud.hide();
    this.hud.hideMatchEnd();
    this.hud.hidePrompt();
    this.hud.hideRoundBanner();
    document.getElementById('pause-overlay').classList.add('hidden');
    this.setupMenuShowroom();
    this.menu.showScreen('main');
    this.audio.ambience();
  }

  collectInput() {
    const mobileRead = this.mobileInput.read();
    this.mobileInput.update();
    let input = { ...this.input };
    input.moveX = mobileRead.moveX;
    input.moveZ = mobileRead.moveZ;
    input.lookX = mobileRead.lookX;
    input.lookY = mobileRead.lookY;
    input.jump = mobileRead.jump || this.keys.has('Space');
    input.sprint = mobileRead.sprint || this.keys.has('ShiftLeft') || this.keys.has('ShiftRight');
    input.shoot = mobileRead.shoot || this.mouseDown || this.keys.has('MouseLeft');
    input.reload = mobileRead.reload || this.keys.has('KeyR');
    input.ability = mobileRead.ability || this.keys.has('KeyQ');
    input.special = mobileRead.special || this.keys.has('KeyF');
    input.interact = mobileRead.interact || this.keys.has('KeyE');
    return input;
  }

  handleActionEdges(input) {
    // Reload and abilities are edge-triggered.
    if (input.reload && !this.lastInput?.reload) {
      this.player.weapon.reload();
    }
    if (input.ability && !this.lastInput?.ability) {
      if (this.player.abilityController.tryActive(this.player)) {
        this.hud.abilityFeed(`${this.player.character.active.name} ATIVADA`);
      } else this.audio.ui('error');
    }
    if (input.special && !this.lastInput?.special) {
      if (this.player.abilityController.trySpecial(this.player)) {
        this.hud.abilityFeed(`${this.player.character.special.name} ATIVADA`);
      } else this.audio.ui('error');
    }
    if ((this.keys.has('Digit1')) && !this.lastDigit1) {
      if (this.player.weapon.switchTo('primary')) this.hud.toast('ARMA PRIMÁRIA');
    }
    if ((this.keys.has('Digit2')) && !this.lastDigit2) {
      if (this.player.weapon.switchTo('secondary')) this.hud.toast('PISTOLA');
    }
    this.lastInput = { ...input };
    this.lastDigit1 = this.keys.has('Digit1');
    this.lastDigit2 = this.keys.has('Digit2');
  }

  handleShooting(dt, input) {
    if (!this.player.health.isAlive) return;
    const weapon = this.player.weapon;
    const fireRateMultiplier = this.player.abilityController?.temporaryStats.fireRateMultiplier || 1;
    weapon.fireCooldown = Math.max(0, weapon.fireCooldown - dt * fireRateMultiplier);
    const targets = [...this.map.raycastTargets(), ...this.entities.filter(entity => entity !== this.player && entity.isAlive()).map(entity => entity.mesh)];
    const callbacks = {
      onHit: result => {
        const entity = result.userData.entityId ? this.entities.find(e => e.id === result.userData.entityId) : null;
        if (entity && entity !== this.player && entity.team !== this.player.team) {
          const damage = entity.takeDamage(result.damage, this.player);
          this.stats.damage += damage;
          this.audio.hit();
          this.hud.hitmarker(entity.health.currentHealth <= 0);
          if (entity.health.currentHealth <= 0) {
            this.stats.kills += 1;
            this.hud.killBanner(entity.character.name);
            this.audio.kill();
            this.hud.addKillEntry(this.player.character.name, entity.character.name, weapon.weapon.name);
          }
          this.spawnImpact(result.point, 0xff5b2e);
        } else {
          this.audio.impact();
          this.spawnImpact(result.point, 0xdfe3e8);
        }
      },
      onMiss: () => {
        this.spawnTracer(this.camera.getWorldPosition(new THREE.Vector3()), this.camera.getWorldPosition(new THREE.Vector3()).add(this.camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(12)), false);
      },
    };
    if (input.shoot) {
      const fired = weapon.tryFire(input.shoot, targets, callbacks);
      if (fired) {
        this.audio.shot(weapon.weapon.sound, 0);
        this.spawnTracer(this.camera.getWorldPosition(new THREE.Vector3()), this.camera.getWorldPosition(new THREE.Vector3()).add(this.camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(24)), false);
        this.spawnMuzzleFlash();
      }
    }
  }

  spawnTracer(origin, target, hit = false) {
    const geometry = new THREE.BufferGeometry().setFromPoints([origin, target]);
    const material = new THREE.LineBasicMaterial({ color: hit ? 0xff5b2e : 0xe4f0ff, transparent: true, opacity: 0.55 });
    const line = new THREE.Line(geometry, material);
    this.scene.add(line);
    this.tracers.push({ mesh: line, timer: 0.08 });
  }

  spawnImpact(point, color = 0xdfe3e8) {
    if (!this.settings.get('particles')) return;
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.08, 6, 4), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.7 }));
    mesh.position.copy(point);
    this.scene.add(mesh);
    this.impacts.push({ mesh, timer: 0.2 });
  }

  spawnMuzzleFlash() {
    if (!this.settings.get('particles')) return;
    const flash = new THREE.Mesh(new THREE.SphereGeometry(0.08, 6, 4), new THREE.MeshBasicMaterial({ color: 0xffd9a6, transparent: true, opacity: 0.7 }));
    const position = this.camera.getWorldPosition(new THREE.Vector3()).add(this.camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(0.4));
    flash.position.copy(position);
    this.scene.add(flash);
    this.impacts.push({ mesh: flash, timer: 0.08 });
  }

  updateEffects(dt) {
    for (let i = this.tracers.length - 1; i >= 0; i -= 1) {
      const tracer = this.tracers[i];
      tracer.timer -= dt;
      tracer.mesh.material.opacity = Math.max(0, tracer.timer / 0.08 * 0.55);
      if (tracer.timer <= 0) {
        this.scene.remove(tracer.mesh);
        tracer.mesh.geometry.dispose();
        tracer.mesh.material.dispose();
        this.tracers.splice(i, 1);
      }
    }
    for (let i = this.impacts.length - 1; i >= 0; i -= 1) {
      const impact = this.impacts[i];
      impact.timer -= dt;
      impact.mesh.material.opacity = Math.max(0, impact.timer / 0.2 * 0.7);
      impact.mesh.scale.setScalar(1 + (0.2 - impact.timer) * 3);
      if (impact.timer <= 0) {
        this.scene.remove(impact.mesh);
        impact.mesh.geometry.dispose();
        impact.mesh.material.dispose();
        this.impacts.splice(i, 1);
      }
    }
  }

  updateEntities(dt, input) {
    this.player.update(dt, input);
    this.entities.forEach(entity => {
      if (entity === this.player) return;
      entity.update(dt, this);
    });
    this.abilityController?.update(dt, this.entities, this.map);
  }

  handleBomb(dt, input) {
    if (!this.bomb) return;
    const player = this.player;
    if (player.isAlive()) {
      if (player.team === 'attackers') {
        if (bombCanPlant(this.bomb, player)) {
          if (this.bomb.state === BombState.NOT_PLANTED && input.interact) this.bomb.startPlant(player, false);
          if (this.bomb.state === BombState.PLANTING) this.bomb.updatePlant(dt, input.interact);
        }
      } else if (player.team === 'defenders') {
        if (bombCanDefuse(this.bomb, player)) {
          if (this.bomb.state === BombState.PLANTED && input.interact) this.bomb.startDefuse(player, false);
          if (this.bomb.state === BombState.DEFUSING) this.bomb.updateDefuse(dt, input.interact);
        }
      }
    }
    // Bot plants/defuses are driven inside their own controller, so update generic timers here.
    if (this.bomb.state === BombState.PLANTING && this.bomb.isBotAction) this.bomb.updatePlant(dt, true);
    if (this.bomb.state === BombState.DEFUSING && this.bomb.isBotAction) this.bomb.updateDefuse(dt, true);
    const exploded = this.bomb.update(dt);
    if (exploded) this.round.onBombExploded();
    if (this.bomb.state === BombState.DEFUSED) {
      this.round.onBombDefused();
    }
    if (this.bomb.state === BombState.PLANTED && this.round.state === RoundState.ACTIVE) {
      this.round.setState(RoundState.BOMB_PLANTED);
    }
  }

  updateRound(dt) {
    this.round?.update(dt);
  }

  animate() {
    requestAnimationFrame(() => this.animate());
    const dt = Math.min(0.05, this.clock.getDelta());
    if (this.mode === 'menu') {
      this.updateMenu(dt);
      this.renderer.render(this.scene, this.camera);
      return;
    }
    if (this.paused) {
      this.renderer.render(this.scene, this.camera);
      return;
    }
    const input = this.collectInput();
    this.handleActionEdges(input);
    this.updateEntities(dt, input);
    this.handleShooting(dt, input);
    this.handleBomb(dt, input);
    this.updateEffects(dt);
    this.updateRound(dt);
    this.interaction.update({ player: this.player, bomb: this.bomb, round: this.round });
    this.hud.update(this, dt);
    this.map?.update(dt);
    this.renderer.render(this.scene, this.camera);
  }

  updateMenu(dt) {
    if (this.previewMesh) {
      this.previewYaw = THREE.MathUtils.lerp(this.previewYaw, this.previewTargetYaw, 1 - Math.pow(0.001, dt));
      this.previewMesh.group.rotation.y = this.previewYaw;
      this.previewMesh.animate(dt, 0, true, true);
    }
    const targetPosition = new THREE.Vector3(
      Math.sin(this.previewYaw + Math.PI) * this.previewDistance,
      1.35 + this.previewPitch * 2,
      Math.cos(this.previewYaw + Math.PI) * this.previewDistance,
    );
    this.camera.position.lerp(targetPosition, 1 - Math.pow(0.001, dt));
    this.camera.lookAt(0, 1.15, 0);
    this.camera.fov = 45;
    this.camera.updateProjectionMatrix();
  }
}

function bombCanPlant(bomb, player) {
  return bomb.state === BombState.NOT_PLANTED && bomb.canPlant(player);
}

function bombCanDefuse(bomb, player) {
  return bomb.state === BombState.PLANTED && bomb.canDefuse(player);
}

